/* بيانات باب mumin: تُحمَّل عند أول فتح للقسم */
window.MUMIN = {"ch":[{"id":"haqq","t":"المؤمنون حقاً","d":"الآيات التي وُصف فيها المؤمنون بأنهم «المؤمنون حقاً» أو «إنما المؤمنون»: وجل القلب، وعدم الارتياب، والتسليم لحكم الله ورسوله، والوفاء بالعهد، والإيثار، وأخوة الإيمان."},{"id":"falah","t":"المؤمنون الذين أفلحوا","d":"صفات الفلاح كما سردتها مطلع سورة «المؤمنون»: الخشوع في الصلاة، والإعراض عن اللغو، والزكاة، وحفظ الفروج، ورعاية الأمانات والعهود، والمحافظة على الصلوات، ثم وراثة الفردوس."},{"id":"rahman","t":"عباد الرحمن","d":"الصفات التي ختمت بها سورة الفرقان وصف «عباد الرحمن»: التواضع والحلم، وقيام الليل، والخوف من جهنم، والاعتدال في الإنفاق، واجتناب الكبائر والتوبة منها، والصدق، والدعاء بصلاح الذرية، وجزاؤهم."},{"id":"mutaqin","t":"صفات المتقين والمحسنين","d":"الآيات التي عدّدت صفات المتقين والمحسنين والصادقين: الإيمان بالغيب، وأركان البر، وكظم الغيظ والعفو، والصبر والصدق، وقيام الليل والإنفاق والاستغفار بالأسحار."},{"id":"maarij","t":"الإنسان الهلوع واستثناء المصلين","d":"الآيات التي وصفت طبع الإنسان وما يخرجه منه من الصفات التي ذكرها الله لأهل الصلاة في سورة المعارج: الدوام على الصلاة، والحق المعلوم في المال، والتصديق بيوم الدين، والأمانة، والشهادة."},{"id":"tahim","t":"التائبون العابدون ومن لهم البشرى","d":"الآيات التي جمعت أوصافاً كثيرة في موضع واحد: «التائبون العابدون الحامدون»، والصفات العشر المشتركة للمؤمنين والمؤمنات، والأبرار، وأهل الشورى والتوكل، وأولو الألباب."},{"id":"qalb","t":"أعمال القلب والباطن","d":"الآيات التي تتناول باطن المؤمن: خشوع القلب، ولينه عند سماع القرآن، وطمأنينته بذكر الله، والتفكر في خلق السماوات والأرض، ومحبة الإيمان، ونزول السكينة."},{"id":"khuluq","t":"أخلاق المؤمنين مع الناس","d":"الآيات التي وصفت معاملة المؤمنين بعضهم لبعض ولغيرهم: الرحمة بينهم، والتواضع للمؤمنين، والأمر بالمعروف، واجتناب الكبائر، والغفران عند الغضب."},{"id":"thamarat","t":"ثمرات الإيمان وسنن الله مع المؤمنين","d":"الآيات التي بيّنت ما وعد الله به المؤمنين: أولياؤه لا خوف عليهم، وتنزل الملائكة على المستقيمين، والابتلاء ليتبين الصادق، والاستخلاف والتمكين، والعلو بالإيمان."}],"tp":[{"id":"anfal","ch":"haqq","t":"المؤمنون حقاً: وجل القلب وزيادة الإيمان والتوكل","e":"وجل القلب عند ذكر الله وزيادة الإيمان بالتلاوة والتوكل وإقامة الصلاة والإنفاق في وصف «المؤمنين حقاً».","ay":[[8,2,4]],"q":[{"bk":"saadi","s":8,"ay":2,"x":"ولما كان الإيمانُ قسمين: إيماناً كاملاً يترتَّب عليه المدح والثناء والفوزُ التامُّ، وإيماناً دون ذلك؛ ذَكَرَ الإيمانَ الكامل، فقال:{إنما المؤمنون}: الألف واللام للاستغراق لشرائع الإيمان، {الذين إذا ذُكِرَ اللهُ وَجِلَتۡ قلوبُهم}؛ أي: خافت ورهبت فأوجبت لهم خشية الله تعالى الانكفافَ عن المحارم؛ فإنَّ خوف الله تعالى أكبر علاماته أن يَحْجُزَ صاحبَه عن الذنوب.","w":"السعدي","en":"Al-Sa'di: faith is of two kinds, complete faith that earns praise and full success, and a lesser faith, so Allah mentions the complete one: 'those who, when Allah is mentioned, their hearts tremble' means they fear and are in awe, so fear of Allah holds them back from what is forbidden; the greatest sign of fearing Allah is that it restrains its owner from sins."},{"bk":"saadi","s":8,"ay":2,"x":"ووجه ذلك أنَّهم يلقون له السمع ويحضِرون قلوبهم لتدبُّره؛ فعند ذلك يزيد إيمانهم؛ لأنَّ التدبُّر من أعمال القلوب، ولأنَّه لا بدَّ أنْ يبيِّن لهم معنىً كانوا يجهلونَه ويتذكَّرون ما كانوا نَسوه أو يُحْدِثَ في قلوبهم رغبةً في الخير واشتياقاً إلى كرامة ربِّهم أو وَجَلاً من العقوبات وازدجاراً عن المعاصي، وكلُّ هذا مما يزداد به الإيمان.","w":"السعدي","en":"Al-Sa'di: their faith grows when His verses are recited because they lend their ears and bring their hearts to reflect, and reflection is a deed of the heart; it shows them a meaning they did not know, reminds them of what they had forgotten, or stirs in them a desire for good and longing for their Lord's generosity, or dread of punishment and restraint from sins; all of this increases faith."},{"bk":"ibnkathir","s":8,"ay":2,"x":"وَهَذِهِ صِفَةُ الْمُؤْمِنِ حَقَّ الْمُؤْمِنِ، الَّذِي إِذَا ذُكِرَ اللَّهُ وَجِلَ قَلْبُهُ، أَيْ: خَافَ مِنْهُ، فَفَعَلَ أَوَامِرَهُ، وَتَرَكَ زَوَاجِرَهُ.","w":"ابن كثير","en":"Ibn Kathir: this is the description of the true believer: when Allah is mentioned his heart fears Him, so he does what He commanded and leaves what He forbade."}]},{"id":"hujurat15","ch":"haqq","t":"«ثم لم يرتابوا وجاهدوا بأموالهم وأنفسهم»","e":"اشتراط عدم الارتياب والجهاد بالمال والنفس في وصف الصادقين.","ay":[[49,15,15]],"q":[{"bk":"saadi","s":49,"ay":15,"x":"وشرط تعالى في الإيمان عدم الريب؛ أي: الشكِّ؛ لأنَّ الإيمان النافع هو الجزم اليقينيُّ بما أمر الله بالإيمان به، الذي لا يعتريه شكٌّ بوجه من الوجوه.","w":"السعدي","en":"Al-Sa'di: Allah made the absence of doubt a condition of faith, because the faith that benefits is firm certainty in what Allah commanded us to believe, with no doubt in it from any side."},{"bk":"ibnkathir","s":49,"ay":15,"x":"وَقَوْلُهُ: ﴿إِنَّمَا الْمُؤْمِنُونَ﴾ أَيْ: إِنَّمَا الْمُؤْمِنُونَ الكُمَّل ﴿الَّذِينَ آمَنُوا بِاللَّهِ وَرَسُولِهِ ثُمَّ لَمْ يَرْتَابُوا﴾ أَيْ: لَمْ يَشُكُّوا وَلَا تَزَلْزَلُوا، بَلْ ثَبَتُوا عَلَى حَالٍ وَاحِدَةٍ، وَهِيَ التَّصْدِيقُ الْمَحْضُ، ﴿وَجَاهَدُوا بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ فِي سَبِيلِ اللَّهِ﴾ أَيْ: وَبَذَلُوا مُهَجَهُمْ وَنَفَائِسَ أَمْوَالِهِمْ فِي طَاعَةِ اللَّهِ وَرِضْوَانِهِ …","w":"ابن كثير","en":"Ibn Kathir: 'Only the perfect believers are those who believe in Allah and His Messenger then do not doubt' means they did not waver but stayed in one state, pure belief; 'and strive with their wealth and their lives in the way of Allah' means they gave their lives and their most precious wealth in obeying Allah and seeking His pleasure."}]},{"id":"nur62","ch":"haqq","t":"المؤمنون عند الأمر الجامع: الاستئذان من الرسول","e":"أدب المؤمنين عند الاجتماع على أمر جامع واستئذانهم قبل الانصراف.","ay":[[24,62,62]],"q":[{"bk":"saadi","s":24,"ay":62,"x":"هذا إرشادٌ من الله لعبادِهِ المؤمنين أنَّهم إذا كانوا مع الرسول - صلى الله عليه وسلم - على أمرٍ جامع؛ أي: من ضرورتِهِ أو مصلحتِهِ أن يكونوا فيه جميعاً؛ كالجهاد والمشاورة ونحو ذلك من الأمور التي يشتركُ فيها المؤمنون؛ فإنَّ المصلحة تقتضي اجتماعُهم عليه وعدمُ تفرُّقهم؛ فالمؤمنُ بالله ورسوله حقًّا لا يذهبُ لأمرٍ من الأمور؛ لا يرجِعُ لأهلِهِ، ولا يذهبُ لبعض الحوائج التي يشذُّ بها عنهم؛ إلاَّ بإذنٍ من الرسول أو نائبِهِ من بعدِهِ، فجعل موجَبَ الإيمان عدمَ الذَّهاب إلاَّ بإذنٍ، ومَدَحَهم على فعلهم هذا وأدَبِهِم مع رسولِهِ وولي الأمر منهم …","w":"السعدي","en":"Al-Sa'di: this is guidance for the believers that when they are with the Messenger on a matter that needs everyone, such as jihad or consultation, where the interest requires them to stay together, the true believer does not leave for any need without permission from the Messenger or his deputy after him; Allah made not leaving without permission a requirement of faith and praised them for this and for their manners with the Messenger and those in authority."},{"bk":"ibnkathir","s":24,"ay":62,"x":"وَهَذَا أَيْضًا أَدَبٌ أَرْشَدَ اللَّهُ عبادَه الْمُؤْمِنِينَ إِلَيْهِ، فَكَمَا أَمَرَهُمْ بِالِاسْتِئْذَانِ عِنْدَ الدُّخُولِ، كَذَلِكَ أَمْرَهُمْ بِالِاسْتِئْذَانِ عِنْدَ الِانْصِرَافِ -لَا سِيَّمَا إِذَا كَانُوا فِي أَمْرٍ جَامِعٍ مَعَ الرَّسُولِ، صَلَوَاتُ اللَّهِ وَسَلَامُهُ عَلَيْهِ، مِنْ صَلَاةِ جُمُعَةٍ أَوْ عِيدٍ أَوْ جَمَاعَةٍ، أَوِ اجْتِمَاعٍ لِمَشُورَةٍ وَنَحْوِ ذَلِكَ -أَمْرَهُمُ اللَّهُ تَعَالَى أَلَّا يَنْصَرِفُوا عَنْهُ وَالْحَالَةُ هَذِهِ إِلَّا بَعْدَ اسْتِئْذَانِهِ وَمُشَاوَرَتِهِ","w":"ابن كثير","en":"Ibn Kathir: this too is a manner Allah taught the believers: as He ordered them to ask permission when entering, so He ordered them to ask permission when leaving, especially when with the Messenger in a gathering such as the Friday or Eid prayer, a congregation or a consultation, not to leave except after asking his permission and consulting him."}]},{"id":"nur51","ch":"haqq","t":"«سمعنا وأطعنا»: قول المؤمنين إذا دُعوا إلى حكم الله","e":"قول المؤمنين إذا دُعوا إلى حكم الله ورسوله، ووصفهم بالفلاح.","ay":[[24,51,52]],"q":[{"bk":"saadi","s":24,"ay":51,"x":"أي: {إنَّما كان قولَ المؤمنين}: حقيقةً، الذين صَدَّقوا إيمانَهم بأعمالهم حين يدعون {إلى الله ورسولِهِ لِيَحۡكُم بينَهم}: سواء وافق أهواءهم أو خالفها، {أنۡ يقولوا سَمِعۡنا وأطَعۡنا}؛ أي: سمعنا حكم الله ورسولِهِ وأجَبْنا مَنْ دعانا إليه وأطعنا طاعةً تامةً سالمةً من الحرج.","w":"السعدي","en":"Al-Sa'di: the saying of the true believers, who proved their faith by their deeds, when they are called to Allah and His Messenger to judge between them, whether it agrees with their desires or not, is only 'We hear and we obey': we heard the ruling of Allah and His Messenger, we answered whoever called us to it, and we obeyed fully, with no reluctance."},{"bk":"ibnkathir","s":24,"ay":51,"x":"ثُمَّ أَخْبَرَ تَعَالَى عَنْ صِفَةِ الْمُؤْمِنِينَ الْمُسْتَجِيبِينَ لِلَّهِ وَلِرَسُولِهِ، الَّذِينَ لَا يَبْغُونَ دِينًا سِوَى كِتَابِ اللَّهِ وَسُنَّةِ رَسُولِهِ، فَقَالَ: ﴿إِنَّمَا كَانَ قَوْلَ الْمُؤْمِنِينَ إِذَا دُعُوا إِلَى اللَّهِ وَرَسُولِهِ لِيَحْكُمَ بَيْنَهُمْ أَنْ يَقُولُوا سَمِعْنَا وَأَطَعْنَا﴾ أَيْ: سَمْعًا وَطَاعَةً …","w":"ابن كثير","en":"Ibn Kathir: then Allah tells the description of the believers who respond to Him and His Messenger and seek no religion other than the Book of Allah and the Sunna of His Messenger: 'hearing and obeying'; so He described them with success, which is attaining what is sought and being safe from what is feared."}]},{"id":"ahzab36","ch":"haqq","t":"التسليم لقضاء الله ورسوله","e":"أنه لا خيار للمؤمن والمؤمنة فيما قضاه الله ورسوله.","ay":[[33,36,36]],"q":[{"bk":"saadi","s":33,"ay":36,"x":"أي: لا ينبغي ولا يَليقُ بمن اتَّصف بالإيمان إلاَّ الإسراعُ في مرضاة الله ورسولِهِ والهربُ من سَخَطِ الله ورسوله وامتثالُ أمرِهما واجتنابُ نهيِهما؛ فلا يليقُ بمؤمنٍ ولا مؤمنةٍ، {إذا قضى اللهُ ورسولُه أمراً}: من الأمور وحَتَّما به وألزما به {أن يكون لَهُمُ الخِيَرَةُ من أمرِهم}؛ أي: الخيار هل يفعلونَه أم لا؟","w":"السعدي","en":"Al-Sa'di: it is fitting for one who has faith only to hasten to the pleasure of Allah and His Messenger, flee their displeasure and carry out what they command and avoid what they forbid; so it does not befit a believing man or woman, when Allah and His Messenger have decreed a matter and made it binding, to have a choice about whether to do it or not."},{"bk":"ibnkathir","s":33,"ay":36,"x":"قَالَ الْعَوْفِيُّ، عَنِ ابْنِ عَبَّاسٍ: قَوْلُهُ: ﴿وَمَا كَانَ لِمُؤْمِنٍ وَلا مُؤْمِنَةٍ﴾ الْآيَةِ، وَذَلِكَ أَنَّ رَسُولَ اللَّهِ ﷺ انْطَلَقَ لِيَخْطُبَ عَلَى فَتَاهُ زَيْدِ بْنِ حَارِثَةَ، فَدَخَلَ عَلَى زَيْنَبَ بِنْتِ جَحْشٍ الْأَسَدِيَّةِ فَخَطَبَهَا، فَقَالَتْ: لَسْتُ بِنَاكِحَتِهِ، فَقَالَ رَسُولُ اللَّهِ ﷺ: \"بَلْ فَانْكِحِيهِ\". قَالَتْ: يَا رَسُولَ اللَّهِ، أُؤَامَرُ فِي نَفْسِي. فَبَيْنَمَا هُمَا يَتَحَدَّثَانِ أَنْزَلَ اللَّهُ هَذِهِ الْآيَةَ عَلَى رَسُولِهِ ﷺ: ﴿وَمَا كَانَ لِمُؤْمِنٍ وَلا مُؤْمِنَةٍ إِذَا قَضَى اللَّهُ وَرَسُولُهُ أَمْرًا﴾ الْآيَةَ، قَالَتْ: قَدْ رَضِيتُهُ لِي مُنْكِحًا يَا رَسُولَ اللَّهِ؟","w":"ابن كثير","en":"Ibn Kathir: al-Awfi reported from Ibn Abbas on the verse that the Messenger of Allah set out to propose on behalf of his freedman Zayd ibn Haritha, so he went to Zaynab bint Jahsh al-Asadiyya and proposed to her for him; she said she would not marry him; he said 'Rather, marry him'; she said she would consult herself; while they were speaking Allah revealed 'It is not for a believing man or woman, when Allah and His Messenger have decided a matter...'; she said, 'Messenger of Allah, I accept him as my husband.'"}]},{"id":"sidq","ch":"haqq","t":"«رجال صدقوا ما عاهدوا الله عليه»","e":"صدق رجال من المؤمنين فيما عاهدوا الله عليه وثباتهم وعدم تبديلهم.","ay":[[33,23,24]],"q":[{"bk":"saadi","s":33,"ay":23,"x":"ولما ذكر أنَّ المنافقين عاهدوا الله لا يولُّون الأدبار ونقضوا ذلك العهد؛ ذكر وفاء المؤمنين به، فقال:{من المؤمنينَ رجالٌ صَدَقوا ما عاهَدوا الله عليه}؛ أي: وَفَّوْا به وأتموُّه وأكملوه، فبذلوا مُهَجَهُم في مرضاتِهِ، وسبَّلوا نفوسهم في طاعته.","w":"السعدي","en":"Al-Sa'di: after mentioning that the hypocrites made a covenant with Allah not to turn their backs and then broke it, He mentions the believers' faithfulness to it: 'Among the believers are men who were true to what they promised Allah' means they fulfilled it, completed it and perfected it, giving their lives for His pleasure and devoting themselves to obeying Him."},{"bk":"ibnkathir","s":33,"ay":23,"x":"لمَّا ذَكَرَ عَنِ الْمُنَافِقِينَ أَنَّهُمْ نَقَضُوا الْعَهْدَ الَّذِي كَانُوا عَاهِدُوا اللَّهَ عَلَيْهِ لَا يُوَلُّونَ الْأَدْبَارَ، وَصَفَ الْمُؤْمِنِينَ بِأَنَّهُمُ اسْتَمَرُّوا عَلَى الْعَهْدِ وَالْمِيثَاقِ وَ ﴿صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ﴾ ، قَالَ بَعْضُهُمْ: أَجْلَهُ.","w":"ابن كثير","en":"Ibn Kathir: after mentioning that the hypocrites broke the covenant they had made with Allah not to flee, He described the believers as having held to the covenant and pledge: 'They were true to what they promised Allah; among them is he who has fulfilled his vow', and some said that means his term of life."}]},{"id":"hashr9","ch":"haqq","t":"الإيثار ومحبة المهاجر: صفة الأنصار","e":"إيثار الأنصار على أنفسهم ومحبتهم لمن هاجر إليهم وسلامة صدورهم.","ay":[[59,9,9]],"q":[{"bk":"saadi","s":59,"ay":9,"x":"ومن أوصاف الأنصار التي فاقوا بها غيرهم وتميَّزوا بها عمَّن سواهم الإيثار، وهو أكمل أنواع الجود، وهو الإيثار بمحابِّ النفس من الأموال وغيرها، وبذلها للغيرِ، مع الحاجة إليها، بل مع الضَّرورة والخَصاصة …","w":"السعدي","en":"Al-Sa'di: and among the qualities of the Ansar by which they surpassed others and were distinguished from them is preferring others, 'and they prefer others over themselves even if they are in need'; it is the most perfect kind of generosity, to give up what the self loves of wealth and other things and give it to another while needing it oneself, even in dire need, and this comes only from a pure character and from love of Allah placed above the self's desires and pleasures."},{"bk":"ibnkathir","s":59,"ay":9,"x":"وَقَوْلُهُ: ﴿وَيُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ﴾ يَعْنِي: حَاجَةً، أَيْ: يُقَدِّمُونَ الْمَحَاوِيجَ عَلَى حَاجَةِ أَنْفُسِهِمْ، وَيَبْدَءُونَ بِالنَّاسِ قَبَلَهُمْ فِي حَالِ احْتِيَاجِهِمْ إِلَى ذَلِكَ.","w":"ابن كثير","en":"Ibn Kathir: 'and they prefer others over themselves even if they are in need' means they put those in need ahead of their own need and begin with other people before themselves even when they themselves need it."}]},{"id":"ikhwa","ch":"haqq","t":"«إنما المؤمنون إخوة»","e":"عقد الأخوة بين المؤمنين وما يترتب عليه من الإصلاح والمحبة.","ay":[[49,10,10]],"q":[{"bk":"saadi","s":49,"ay":10,"x":"{إنَّما المؤمنونَ إخوةٌ}: هذا عقدٌ عقدَه الله بين المؤمنين؛ أنَّه إذا وجد من أيِّ شخصٍ كان في مشرق الأرض ومغربها الإيمانُ بالله وملائكته وكتبه ورسله واليوم الآخر؛ فإنَّه أخٌ للمؤمنين أخوَّةً توجبُ أن يحبَّ له المؤمنون ما يحبُّون لأنفسهم، ويكرهوا له ما يكرهون لأنفسهم …","w":"السعدي","en":"Al-Sa'di: 'The believers are but brothers' is a bond Allah tied among the believers: whoever, anywhere in the east or west, believes in Allah, His angels, books, messengers and the Last Day is a brother to the believers, a brotherhood that obliges them to love for him what they love for themselves and to dislike for him what they dislike for themselves."},{"bk":"ibnkathir","s":49,"ay":10,"x":"وَقَوْلُهُ: ﴿إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ﴾ أَيِ: الْجَمِيعُ إِخْوَةٌ فِي الدِّينِ، كَمَا قَالَ رَسُولُ اللَّهِ ﷺ: \"الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يُسْلِمُهُ\" .","w":"ابن كثير","en":"Ibn Kathir: 'The believers are but brothers' means all of them are brothers in religion, as the Messenger of Allah said: 'A Muslim is the brother of a Muslim; he does not wrong him nor abandon him.'"}]},{"id":"khushu","ch":"falah","t":"الفلاح والخشوع في الصلاة","e":"الفلاح للمؤمنين الذين هم في صلاتهم خاشعون.","ay":[[23,1,2]],"q":[{"bk":"saadi","s":23,"ay":1,"x":"فقوله: {قد أفلح المؤمنونَ}؛ أي: قد فازوا وسَعِدوا ونجحوا، وأدركوا كلَّ ما يرام، المؤمنون الذين آمنوا بالله، وصدَّقوا المرسلين.","w":"السعدي","en":"Al-Sa'di: 'The believers have succeeded' means they have won, become happy, achieved and attained all that is sought: the believers who believed in Allah and affirmed the messengers."},{"bk":"saadi","s":23,"ay":1,"x":"الذين من صفاتهم الكاملة أنهم {في صلاتهم خاشِعونَ}: والخشوع في الصلاة هو حضورُ القلب بين يدي الله تعالى، مستحضراً لقربه، فيسكن لذلك قلبه، وتطمئن نفسه، وتسكن حركاتُه، ويقلُّ التفاتُه، متأدِّباً بين يدي ربِّه، مستحضراً جميع ما يقوله ويفعله في صلاتِهِ من أول صلاته إلى آخرها، فتنتفي بذلك الوساوس والأفكار الرديَّة، وهذا روح الصلاة والمقصود منها …","w":"السعدي","en":"Al-Sa'di: among their perfect qualities is that they are 'humble in their prayer'; humility in prayer is the presence of the heart before Allah, keeping His nearness in mind, so the heart is still, the soul at rest, the movements calm and turning about is rare, in good manners before one's Lord, keeping in mind everything one says and does from the beginning of the prayer to the end, so that whispers and bad thoughts leave; this is the soul of prayer and its aim."}]},{"id":"laghw","ch":"falah","t":"الإعراض عن اللغو","e":"إعراض المؤمنين عن كل كلام وفعل لا فائدة فيه.","ay":[[23,3,3]],"q":[{"bk":"saadi","s":23,"ay":3,"x":"{والذين هم عن اللغو}: وهو الكلام الذي لا خير فيه ولا فائدة، {معرضون}: رغبةً عنه وتنزيهاً لأنفسهم وترفُّعاً عنه، وإذا مرُّوا باللغو مرُّوا كراماً، وإذا كانوا معرضين عن اللغو؛ فإعراضُهم عن المحرَّم من باب أولى وأحرى، وإذا مَلَكَ العبدُ لسانَه وخَزَنَه إلاَّ في الخير؛ كان مالكاً لأمرِهِ …","w":"السعدي","en":"Al-Sa'di: 'those who turn away from idle talk', which is speech with no good or benefit in it, 'turn away' out of dislike for it, keeping themselves above it; if they pass by idle talk they pass by with dignity, and if they turn away from the idle then turning away from the forbidden is more fitting; when a person controls his tongue and keeps it except for good, he is in control of his affairs."},{"bk":"ibnkathir","s":23,"ay":3,"x":"وَقَالَ : ﴿وَالَّذِينَ هُمْ عَنِ اللَّغْوِ مُعْرِضُونَ﴾ أَيْ: عَنِ الْبَاطِلِ، وَهُوَ يَشْمَلُ: الشِّرْكَ -كَمَا قَالَهُ بَعْضُهُمْ-وَالْمَعَاصِي -كَمَا قَالَهُ آخَرُونَ -وَمَا لَا فَائِدَةَ فِيهِ مِنَ الْأَقْوَالِ وَالْأَفْعَالِ، كَمَا قَالَ تَعَالَى: ﴿وَإِذَا مَرُّوا بِاللَّغْوِ مَرُّوا كِرَامًا﴾ [الْفَرْقَانِ: ٧٢] .","w":"ابن كثير","en":"Ibn Kathir: 'and those who turn away from idle talk' means from falsehood, which includes shirk as some said, and sins as others said, and whatever has no benefit of words and deeds, as Allah said: 'and when they pass by idle talk, they pass by with dignity.'"}]},{"id":"zakat","ch":"falah","t":"أداء الزكاة تزكيةً للنفس والمال","e":"أداء الزكاة وتزكية النفس مع أداء حق المال.","ay":[[23,4,4]],"q":[{"bk":"saadi","s":23,"ay":4,"x":"{والذين هم للزَّكاةِ فاعلون}؛ أي: مؤدُّون لزكاة أموالهم على اختلاف أجناس الأموال؛ مزكين لأنفسهم من أدناس الأخلاق ومساوئ الأعمال التي تزكو النفوس بتركِها وتجنُّبِها؛ فأحسنوا في عبادة الخالق في الخشوع في الصلاة، وأحسنوا إلى خلقه بأداء الزَّكاة.","w":"السعدي","en":"Al-Sa'di: 'those who give zakat' means they pay the zakat of their wealth in all its kinds, and purify themselves of the stains of character and bad deeds, which the souls are purified by leaving and avoiding; so they did good in worshipping the Creator through humility in prayer, and did good to His creation by paying zakat."},{"bk":"ibnkathir","s":23,"ay":4,"x":"وَقَوْلُهُ: ﴿وَالَّذِينَ هُمْ لِلزَّكَاةِ فَاعِلُونَ﴾ : الْأَكْثَرُونَ عَلَى أَنَّ الْمُرَادَ بِالزَّكَاةِ هَاهُنَا زَكَاةُ الْأَمْوَالِ، مَعَ أَنَّ هَذِهِ [الْآيَةَ] مَكِّيَّةٌ، وَإِنَّمَا فُرِضَتِ الزَّكَاةُ بِالْمَدِينَةِ فِي سَنَةِ اثْنَتَيْنِ مِنَ الْهِجْرَةِ.","w":"ابن كثير","en":"Ibn Kathir: most hold that zakat here means the zakat of wealth, even though this verse is Meccan and zakat was only made obligatory in Madina in the second year after the Hijra."}]},{"id":"furuj","ch":"falah","t":"حفظ الفروج","e":"حفظ الفروج إلا على الأزواج وما ملكت اليمين، وبيان العدوان بتجاوز ذلك.","ay":[[23,5,7]],"q":[{"bk":"saadi","s":23,"ay":5,"x":"{والذين هم لفروجهم حافظون}: عن الزِّنا، ومن تمام حفظها تجنُّب ما يدعو إلى ذلك؛ كالنظر واللمس ونحوهما، فحفظوا فروجهم من كلِّ أحدٍ.","w":"السعدي","en":"Al-Sa'di: 'those who guard their chastity' from adultery, and part of fully guarding it is avoiding what leads to it, such as looking and touching and the like, so they guard it from everyone."},{"bk":"ibnkathir","s":23,"ay":5,"x":"وَقَوْلُهُ: ﴿وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ. إِلا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ * فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُولَئِكَ هُمُ الْعَادُونَ …","w":"ابن كثير","en":"Ibn Kathir: 'and those who guard their chastity except from their spouses or those their right hands possess, for then they are not blamed; but whoever seeks beyond that, those are the transgressors.'"}]},{"id":"amana23","ch":"falah","t":"رعاية الأمانات والعهود","e":"رعاية المؤمنين لأماناتهم وعهودهم.","ay":[[23,8,8]],"q":[{"bk":"saadi","s":23,"ay":8,"x":"{والذين هم لأماناتِهِم وعَهۡدِهِم راعونَ}؛ أي: مراعون لها، ضابطون، حافظون، حريصون على القيام بها وتنفيذها.","w":"السعدي","en":"Al-Sa'di: 'those who are keepers of their trusts and their covenants' means they observe them, are careful with them, guard them and are eager to fulfil and carry them out."},{"bk":"ibnkathir","s":23,"ay":8,"x":"وَقَوْلُهُ: ﴿وَالَّذِينَ هُمْ لأمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ﴾ أَيْ: إِذَا اؤْتُمِنُوا لَمْ يَخُونُوا، بَلْ يُؤَدُّونَهَا إِلَى أَهْلِهَا، وَإِذَا عَاهَدُوا أَوْ عَاقَدُوا أَوْفَوْا بِذَلِكَ، لَا كَصِفَاتِ الْمُنَافِقِينَ الَّذِينَ قَالَ فِيهِمْ رَسُولُ اللَّهِ ﷺ: \"آيَةُ الْمُنَافِقِ ثَلَاثٌ: إِذَا حَدَّث كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وإذا اؤتمن خَانَ\".","w":"ابن كثير","en":"Ibn Kathir: it means that when they are trusted they do not betray but deliver trusts to their owners, and when they make a covenant or contract they keep to it, unlike the qualities of the hypocrites about whom the Messenger of Allah said: 'The sign of the hypocrite is three: when he speaks he lies, when he promises he breaks it, and when he is trusted he betrays.'"}]},{"id":"salawat","ch":"falah","t":"المحافظة على الصلوات وميراث الفردوس","e":"المحافظة على الصلوات في أوقاتها، وذكر ميراث الفردوس لأهل هذه الصفات.","ay":[[23,9,11]],"q":[{"bk":"saadi","s":23,"ay":9,"x":"{والذين هم على صَلَواتهم يحافِظونَ}؛ أي: يداومون عليها في أوقاتها وحدودها وأشراطها وأركانها؛ فمدحهم بالخشوع بالصلاة وبالمحافظة عليها، لأنَّه لا يتمُّ أمرُهم إلاَّ بالأمرين؛ فمن يداوِمُ على الصلاة من غير خُشوع أو على الخُشوع من دون محافظةٍ عليها؛ فإنَّه مذمومٌ ناقصٌ.","w":"السعدي","en":"Al-Sa'di: 'and those who guard their prayers' means they keep them up at their times, within their limits, conditions and pillars; so He praised them for humility in prayer and for guarding it, because their matter is complete only with both; whoever keeps up prayer without humility, or humility without guarding it, is blamed and lacking."},{"bk":"saadi","s":23,"ay":10,"x":"{الذين يَرِثونَ الفِرۡدَوۡسَ}: الذي هو أعلى الجنَّة ووسطُها وأفضلُها؛ لأنَّهم حُلُّوا من صفات الخير أعلاها وذروتها، أو المراد بذلك جميع الجنة؛ ليدخلَ بذلك عموم المؤمنين على درجاتهم في مراتبهم كلٌّ بحسب حاله.","w":"السعدي","en":"Al-Sa'di: 'who will inherit al-Firdaws' which is the highest part of Paradise, its middle and its best, because they were adorned with the highest and loftiest qualities of good; or what is meant is all of Paradise, so that believers in general enter by their ranks, each according to his state."},{"bk":"ibnkathir","s":23,"ay":9,"x":"قَالَتِ: كَانَ خُلُقِ رَسُولِ اللَّهِ ﷺ الْقُرْآنَ، فَقَرَأَتْ: ﴿قَدْ أَفْلَحَ الْمُؤْمِنُونَ﴾ حَتَّى انتَهَتْ إِلَى: ﴿وَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْ يُحَافِظُونَ﴾ ، قَالَتْ: هَكَذَا كَانَ خُلُق رَسُولِ اللَّهِ ﷺ.","w":"ابن كثير","en":"Ibn Kathir: she said that the character of the Messenger of Allah was the Quran, and she recited 'The believers have succeeded' until she reached 'and those who guard their prayers', and said: such was the character of the Messenger of Allah."}]},{"id":"hawn","ch":"rahman","t":"«يمشون على الأرض هوناً»: التواضع والحلم","e":"المشي على الأرض هوناً ومخاطبة الجاهلين بالسلام.","ay":[[25,63,63]],"q":[{"bk":"saadi","s":25,"ay":63,"x":"وعبوديَّةٌ لألوهيَّتِهِ وعبادتِهِ ورحمتِهِ، وهي عبوديَّةُ أنبيائِهِ وأوليائِهِ، وهي المراد هنا، ولهذا أضافها إلى اسمه الرحمن؛ إشارةً إلى أنَّهم إنَّما وصلوا إلى هذه الحال بسبب رحمته، فَذَكَرَ [أنَّ] صفاتِهِم أكملُ الصفات ونعوتَهم أفضلُ النعوتِ، فوصَفَهم بأنَّهم {يَمۡشونَ على الأرضِ هَوۡناً}؛ أي: ساكنين متواضعين لله وللخَلْق؛ فهذا وصفٌ لهم بالوقارِ والسَّكينةِ والتَّواضُع لله ولعبادِهِ، {وإذا خاطَبَهُمُ الجاهلونَ}؛ أي: خطابَ جهل؛ بدليل إضافةِ الفعل وإسناده لهذا الوصفِ، {قالوا سلاماً}؛ أي: خاطَبوهم خطاباً يَسْلمونَ فيه من الإثم، ويَسْلَمونَ من مقابلة الجاهل بجهلِهِ، وهذا مدحٌ لهم بالحِلْم الكثير ومقابلة المسيء بالإحسان والعفو عن الجاهل ورزانةِ العقل الذي أوصلهم إلى هذه الحال.","w":"السعدي","en":"Al-Sa'di: Allah described them as 'walking upon the earth humbly', meaning calm and humble before Allah and before people, a description of dignity, calm and humility toward Allah and His servants; 'and when the ignorant address them', meaning with ignorance, 'they say: peace', meaning they answer in a way that keeps them safe from sin and from answering the ignorant with his ignorance; this is praise of their great forbearance, of meeting wrong with good, of pardoning the ignorant and of the steadiness of mind that brought them to this state."},{"bk":"ibnkathir","s":25,"ay":63,"x":"سب هَذِهِ صِفَاتُ عِبَادِ اللَّهِ الْمُؤْمِنِينَ ﴿الَّذِينَ يَمْشُونَ عَلَى الأرْضِ هَوْنًا﴾ أَيْ: بِسَكِينَةٍ وَوَقَارٍ مِنْ غَيْرِ جَبَرية وَلَا اسْتِكْبَارٍ، كَمَا قَالَ: ﴿وَلا تَمْشِ فِي الأرْضِ مَرَحًا إِنَّكَ لَنْ تَخْرِقَ الأرْضَ وَلَنْ تَبْلُغَ الْجِبَالَ طُولا﴾ [الْإِسْرَاءِ: ٣٧] .","w":"ابن كثير","en":"Ibn Kathir: these are the qualities of Allah's believing servants: 'who walk upon the earth humbly' means with calm and dignity, with no arrogance or pride, as He said: 'Do not walk upon the earth exultantly; you will never split the earth nor reach the mountains in height.'"}]},{"id":"layl","ch":"rahman","t":"«يبيتون لربهم سجداً وقياماً»","e":"مبيت عباد الرحمن لربهم ساجدين وقائمين.","ay":[[25,64,64]],"q":[{"bk":"saadi","s":25,"ay":64,"x":"{والذين يَبيتونَ لربِّهم سُجَّداً وقياماً}؛ أي: يكثِرون من صلاةِ الليل مخلِصين فيها لربِّهم متذلِّلين له؛ كما قال تعالى:{تتجافى جُنوبُهم عن المضاجِع يَدۡعونَ رَبَّهم خَوۡفاً وطَمَعاً ومما رَزَقۡناهم يُنفِقون.","w":"السعدي","en":"Al-Sa'di: 'and those who spend the night for their Lord prostrating and standing' means they pray much at night, sincere to their Lord and humbling themselves to Him, as Allah said: 'Their sides forsake their beds, calling upon their Lord in fear and hope, and spend from what We provided them.'"},{"bk":"ibnkathir","s":25,"ay":64,"x":"وَقَوْلُهُ: ﴿وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا﴾ أَيْ: فِي عِبَادَتِهِ وَطَاعَتِهِ، كَمَا قَالَ تَعَالَى: ﴿كَانُوا قَلِيلا مِنَ اللَّيْلِ مَا يَهْجَعُونَ وَبِالأسْحَارِ هُمْ يَسْتَغْفِرُونَ﴾ [الذَّارِيَاتِ: ١٧ -١٨] ، وَقَالَ ﴿تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ﴾ [السَّجْدَةِ: ١٦] وَقَالَ ﴿أَمَّنْ هُوَ قَانِتٌ آنَاءَ اللَّيْلِ سَاجِدًا وَقَائِمًا يَحْذَرُ الآخِرَةَ وَيَرْجُو رَحْمَةَ رَبِّهِ …","w":"ابن كثير","en":"Ibn Kathir: 'and those who spend the night for their Lord prostrating and standing' means in worshipping and obeying Him, as He said: 'They used to sleep but little of the night, and before dawn they would seek forgiveness', and: 'Is one who is devout during the hours of the night, prostrating and standing, fearing the Hereafter and hoping for the mercy of his Lord...'"}]},{"id":"jahannam","ch":"rahman","t":"الخوف من جهنم والدعاء بصرف عذابها","e":"دعاؤهم بصرف عذاب جهنم، ووصفها بأنها ساءت مستقراً ومقاماً.","ay":[[25,65,66]],"q":[{"bk":"saadi","s":25,"ay":65,"x":"{والذين يقولونَ ربَّنا اصرِفۡ عنَّا عذابَ جَهَنَّمَ}؛ أي: ادفعه عنا بالعصمةِ من أسبابِهِ ومغفرةِ ما وَقَعَ منَّا مما هو مقتضٍ للعذاب، {إنَّ عَذابها كانَ غراماً}؛ أي: ملازماً لأهلها بمنزلة ملازمةِ الغريم لغريمه.","w":"السعدي","en":"Al-Sa'di: 'and those who say: Our Lord, turn away from us the punishment of Hell' means push it away from us by protection from its causes and by forgiving what we did that deserves punishment; 'its punishment is ever clinging' means it is always with its people, as a creditor sticks to the debtor."},{"bk":"saadi","s":25,"ay":66,"x":"{إنَّها ساءتۡ مُستقرًّا ومُقاماً}: وهذا منهم على وجه التضرُّع لربِّهم، وبيانِ شدَّةِ حاجتهم إليه، وأنَّهم ليس في طاقتهم احتمالُ هذا العذاب، وليتذكَّروا مِنَّةَ الله عليهم؛ فإنَّ صرف الشدَّةِ بحسب شدتها وفظاعتها يعظُمُ وقعُها، ويشتدُّ الفرحُ بصرفها.","w":"السعدي","en":"Al-Sa'di: 'Indeed it is an evil abode and place of stay': they say this in humble pleading to their Lord and to show how much they need Him, that they cannot bear this punishment, and to remember Allah's favor upon them; for the more severe and terrible a hardship, the greater the impact of its removal and the joy at it."}]},{"id":"infaq","ch":"rahman","t":"الإنفاق بين الإسراف والتقتير","e":"الإنفاق بين الإسراف والتقتير.","ay":[[25,67,67]],"q":[{"bk":"saadi","s":25,"ay":67,"x":"{والذين إذا أنفَقوا}: النفقاتِ الواجبةَ والمستحبةَ {لم يُسۡرِفوا}: بأن يَزيدوا على الحدِّ فيدخُلوا في قسم التبذير، {ولم يَقۡتُروا}: فيدخلوا في باب البُخْل والشُّحِّ، وإهمال الحقوق الواجبة، {وكان}: إنفاقُهم {بينَ ذلك}: بين الإسراف والتقتير {قَواماً}: يبذُلون في الواجبات من الزَّكَواتِ والكفاراتِ والنفقاتِ الواجبةِ وفيما ينبغي على الوجه الذي يَنْبَغي من غير ضررٍ ولا ضِرارٍ، وهذا من عدلهم واقتصادهم.","w":"السعدي","en":"Al-Sa'di: 'those who, when they spend', whether obligatory or recommended spending, 'are neither extravagant', exceeding the limit and falling into waste, 'nor niggardly', falling into miserliness and neglecting obligatory rights; 'and it is between that' between extravagance and tightness 'moderate': they give in what is obligatory, such as zakat, expiations and obligatory maintenance, and in what is fitting in the proper way without harm or damage; this is from their justice and moderation."},{"bk":"ibnkathir","s":25,"ay":67,"x":"وَقَوْلُهُ: ﴿وَالَّذِينَ إِذَا أَنْفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا وَكَانَ بَيْنَ ذَلِكَ قَوَامًا﴾ أَيْ: لَيْسُوا بِمُبَذِّرِينَ في إِنْفَاقِهِمْ فَيَصْرِفُونَ فَوْقَ الْحَاجَةِ، وَلَا بُخَلَاءَ عَلَى أهْليهم فَيُقَصِّرُونَ فِي حَقِّهِمْ فَلَا يَكْفُونَهُمْ، بَلْ عَدْلا خِيَارًا، وَخَيْرُ الْأُمُورِ أَوْسَطُهَا، لَا هَذَا وَلَا هَذَا، ﴿وَكَانَ بَيْنَ ذَلِكَ قَوَامًا﴾ ، كَمَا قَالَ: ﴿وَلا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَى عُنُقِكَ وَلا تَبْسُطْهَا كُلَّ الْبَسْطِ فَتَقْعُدَ مَلُومًا مَحْسُورًا﴾ [الْإِسْرَاءِ: ٢٩] .","w":"ابن كثير","en":"Ibn Kathir: it means they are not wasteful in spending, spending beyond need, nor stingy with their families so that they fall short of their right and do not suffice them, but are just and the best, for the best of matters is the middle one, neither this nor that, 'and it is between that moderate', as He said: 'Do not make your hand tied to your neck, nor extend it fully, or you will sit blamed and regretful.'"}]},{"id":"kabair","ch":"rahman","t":"اجتناب الشرك والقتل والزنا والتوبة منها","e":"اجتناب الشرك وقتل النفس والزنا، وتبديل السيئات حسنات لمن تاب وآمن وعمل صالحاً.","ay":[[25,68,71]],"q":[{"bk":"saadi","s":25,"ay":68,"x":"{والذين لا يَدۡعونَ مع اللهِ إلهاً آخر}: بل يَعْبُدونَه وحدَه مخلصين له الدين حنفاءَ مقبلينَ عليه معرِضين عمَّا سواه، {ولا يَقۡتُلونَ النفسَ التي حرَّمَ اللهُ}: وهي نفسُ المسلم والكافرِ المعاهَد {إلاَّ بالحقِّ}: كقتل النفس بالنفس، وقتل الزاني المحصَن والكافر الذي يَحِلُّ قتله، {ولا يَزۡنونَ}: بل يحفَظون فروجَهم؛ إلاَّ على أزواجِهِم أوْما مَلَكَتْ أيمانُهم، {ومَنۡ يَفۡعَلۡ ذلك}؛ أي: الشرك بالله أو قتل النفس التي حرَّم الله بغير حقٍّ أو الزِّنا؛ فسوف {يَلۡقَ أثاما}.","w":"السعدي","en":"Al-Sa'di: 'those who do not call upon another god with Allah' but worship Him alone, sincere in religion, turning to Him and away from all else; 'and do not kill the soul that Allah has forbidden' which is the soul of a Muslim and of a covenanted non-Muslim, 'except by right', such as a life for a life, the married adulterer, and the disbeliever whose killing is lawful; 'and do not commit adultery', but guard their chastity except with their spouses or those their right hands possess; 'and whoever does that', meaning shirk, killing a forbidden soul or adultery, 'will meet a penalty.'"},{"bk":"saadi","s":25,"ay":70,"x":"{إلاَّ مَن تابَ}: عن هذه المعاصي وغيرِها بأنْ أقْلَعَ عنها في الحال، وندم على ما مضى له من فعلها، وعزم عزماً جازماً أنْ لا يعود، {وآمنَ} بالله إيماناً صحيحاً يقتضي تركَ المعاصي وفعل الطاعات، {وعمل صالحاً}: مما أمر به الشارعُ إذا قَصَدَ به وجه الله؛ {فأولئك يبدِّلُ الله سيئاتِهِم حسناتٍ}؛ أي: تتبدَّل أفعالُهم وأقوالُهم التي كانت مستعدِّة لعمل السيئات، تتبدَّلُ حسناتٍ، فيتبدَّل شِرْكُهم إيماناً، ومعصيتُهم طاعةً …","w":"السعدي","en":"Al-Sa'di: 'except one who repents' from these sins and others by stopping at once, regretting what is past and resolving firmly not to return, 'and believes' with sound faith that requires leaving sins and doing acts of obedience, 'and does righteous deeds' as the Lawgiver commanded, seeking Allah's face; 'for those Allah will change their bad deeds into good ones', meaning their deeds and words that were ready for evil are changed into good, so their shirk becomes faith and their disobedience obedience …"}]},{"id":"zur","ch":"rahman","t":"«لا يشهدون الزور»: الصدق والإعراض عن اللغو والتذكر بالآيات","e":"ترك شهادة الزور، والمرور باللغو كراماً، وتلقّي آيات الله بالقبول.","ay":[[25,72,73]],"q":[{"bk":"saadi","s":25,"ay":72,"x":"{والذين لا يشهدون الزُّورَ}؛ أي: لا يحضُرونَ الزُّورَ؛ أي: القول والفعل المحرم، فيجتنبون جميع المجالس المشتملة على الأقوال المحرَّمة أو الأفعال المحرَّمة؛ كالخوض في آيات الله، والجدال الباطل، والغيبة، والنميمة، والسب، والقذف، والاستهزاء، والغناء المحرم، وشرب الخمر، وفرش الحرير والصور ...","w":"السعدي","en":"Al-Sa'di: 'those who do not witness falsehood' means they do not attend falsehood, the forbidden word or deed, so they avoid all gatherings that include forbidden speech or deeds, such as plunging into arguments about Allah's verses, false disputing, backbiting, slander, insult, false accusation, mockery, forbidden singing, drinking wine, spreading silk and pictures ..."},{"bk":"saadi","s":25,"ay":73,"x":"{والذين إذا ذُكِّروا بآياتِ ربِّهم}: التي أمَرَهُم باستماعها والاهتداء بها {لم يَخِرُّوا عليها صُمًّا وعُمياناً}؛ أي: لم يقابلوها بالإعراض عنها، والصمم عن سماعها، وصرف النظر والقلوب عنها كما يفعله من لم يؤمن بها ويصدق …","w":"السعدي","en":"Al-Sa'di: 'those who, when reminded of the verses of their Lord' which He commanded them to listen to and be guided by, 'do not fall upon them deaf and blind', meaning they do not meet them with turning away, deafness to hearing them and turning eyes and hearts from them, as those who do not believe and affirm do."}]},{"id":"dhurriyya","ch":"rahman","t":"دعاء قرة الأعين وإمامة المتقين","e":"دعاء عباد الرحمن بصلاح الأزواج والذرية وبأن يكونوا للمتقين إماماً.","ay":[[25,74,74]],"q":[{"bk":"saadi","s":25,"ay":74,"x":"{والذين يقولونَ ربَّنا هَبۡ لنا من أزواجِنا}؛ أي: قُرَنائِنا من أصحابٍ وأقرانٍ وزوجاتٍ، {وذُرِّيَّاتِنا قُرَّةَ أعينٍ}؛ أي: تَقَرُّ بهم أعيننا، وإذا اسْتَقْرَأنا حالَهم وصفاتِهِم؛ عَرَفْنا من هِمَمِهِم وعلوِّ مرتبتِهِم [أنَّهم لا تَقَرُّ أَعْيُنُهم حَتَّى يَرَوهُم مُطِيعين لربِّهم عَالِمين عَامِلين وهذا كما أنه دعاء لأزواجهم] وذُرِّيَّاتِهم في صلاحهم؛ فإنَّه دعاءٌ لأنفسهم؛ لأنَّ نفعه يعودُ عليهم، ولهذا جعلوا ذلك هبةً لهم، فقالوا:{هَبۡ لنا}، بل دعاؤهم يعودُ إلى نفع عموم المسلمين …","w":"السعدي","en":"Al-Sa'di: 'those who say: Our Lord, grant us from our spouses and offspring comfort for our eyes' means our companions, peers and wives, and our offspring, with whom our eyes find joy; when we look at their state and qualities we know from their aspirations and high rank that their eyes find no joy until they see their spouses and offspring obedient to their Lord, knowing and acting, and this is as much a prayer for themselves as for their families, since its benefit returns to them; that is why they asked it as a gift: 'grant us', and their prayer benefits all Muslims, because the righteousness of those mentioned becomes a cause of the righteousness of many connected to them."},{"bk":"ibnkathir","s":25,"ay":74,"x":"وَقَوْلُهُ: ﴿وَالَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ﴾ يَعْنِي: الَّذِينَ يَسْأَلُونَ اللَّهَ أَنْ يُخْرِجَ مِنْ أَصْلَابِهِمْ وَذُرِّيَّاتِهِمْ مَنْ يُطِيعُهُ وَيَعْبُدُهُ وَحْدَهُ لَا شَرِيكَ لَهُ.","w":"ابن كثير","en":"Ibn Kathir: 'those who say: Our Lord, grant us from our spouses and offspring comfort for our eyes' means those who ask Allah to bring out of their loins and offspring those who obey Him and worship Him alone with no partner."}]},{"id":"ghurfa","ch":"rahman","t":"جزاء عباد الرحمن: الغرفة والتحية والسلام","e":"جزاء عباد الرحمن بالغرفة والتحية والسلام والخلود.","ay":[[25,75,76]],"q":[{"bk":"saadi","s":25,"ay":75,"x":"ولهذا لما كانت هِمَمُهُم ومطالِبُهم عاليةً، كان الجزاء من جنس العمل، فجازاهم بالمنازل العاليات، فقال:{أولئك يُجۡزَوۡنَ الغرفةَ بما صبروا}؛ أي: المنازل الرفيعة والمساكن الأنيقة الجامعة لكلِّ ما يشتهَى وتلذُّه الأعين، وذلك بسبب صبرِهِم نالوا ما نالوا؛ كما قال تعالى:{والملائكةُ يَدۡخُلون عليهم مِن كلِّ بابٍ.","w":"السعدي","en":"Al-Sa'di: since their aspirations and requests were high, the reward matched the deed and He repaid them with high stations, saying: 'Those will be rewarded with the high place for their patience', meaning lofty dwellings and beautiful homes containing all that is desired and delights the eyes; they reached what they reached because of their patience, as He said: 'and the angels will enter upon them from every gate.'"},{"bk":"ibnkathir","s":25,"ay":75,"x":"لَمَّا ذَكَرَ تَعَالَى مِنْ أَوْصَافِ عِبَادِهِ الْمُؤْمِنِينَ مَا ذَكَرَ مِنْ [هَذِهِ] الصِّفَاتِ الْجَمِيلَةِ، وَالْأَفْعَالِ وَالْأَقْوَالِ الْجَلِيلَةِ -قَالَ بَعْدَ ذَلِكَ كُلِّهِ: ﴿أُوْلَئِك﴾ أَيْ: الْمُتَّصِفُونَ بِهَذِهِ ﴿يُجْزَوْن﴾ أَيْ: يَوْمَ الْقِيَامَةِ ﴿الْغُرْفَةَ﴾ وَهِيَ الْجَنَّةُ.","w":"ابن كثير","en":"Ibn Kathir: after Allah mentioned of the qualities of His believing servants all these beautiful qualities and noble words and deeds, He said after all that: 'Those', meaning the ones described like this, 'will be rewarded' on the Day of Resurrection 'with the high place', which is Paradise."}]},{"id":"baqara2","ch":"mutaqin","t":"المتقون: الإيمان بالغيب والصلاة والإنفاق واليقين بالآخرة","e":"وصف المتقين بالإيمان بالغيب وإقامة الصلاة والإنفاق والإيمان بما أنزل واليقين بالآخرة.","ay":[[2,2,5]],"q":[{"bk":"saadi","s":2,"ay":3,"x":"ثم وصف المتقين بالعقائد والأعمال الباطنة والأعمال الظاهرة لتضمن التقوى لذلك فقال: {3}{الذين يؤمنون بالغيب} حقيقة الإيمان هو التصديق التام بما أخبرت به الرسل، المتضمن لانقياد الجوارح، وليس الشأن في الإيمان بالأشياء المشاهدة بالحسِّ، فإنه لا يتميز بها المسلم من الكافر، إنما الشأنُ في الإيمان بالغيب الذي لم نره ولم نشاهده، وإنما نؤمن به لخبر الله وخبر رسوله","w":"السعدي","en":"Al-Sa'di: then He described the God-fearing by inner beliefs and deeds and outward deeds, since God-fearing includes them: 'those who believe in the unseen'. The truth of faith is full affirmation of what the messengers reported, which includes the submission of the limbs; faith in things perceived by the senses is no mark that separates the Muslim from the disbeliever, rather the question is faith in the unseen that we have not seen or witnessed and believe only because of the word of Allah and His Messenger."},{"bk":"saadi","s":2,"ay":3,"x":"ثم قال:{ويقيمون الصلاة} لم يقل: يفعلون الصلاة؛ أو يأتون بالصلاة لأنه لا يكفي فيها مجرد الإتيان بصورتها الظاهرة، فإقامة الصلاة، إقامتها ظاهراً، بإتمام أركانها وواجباتها وشروطها، وإقامتها باطناً ، بإقامة روحها وهو حضور القلب فيها وتدبر ما يقول ويفعله منها، فهذه الصلاة هي التي قال الله فيها:{إن الصلاة تنهى عن الفحشاء والمنكر} وهي التي يترتب عليها الثواب، فلا ثواب للعبد من صلاته إلا ما عقل منها، ويدخل في الصلاة فرائضها ونوافلها.","w":"السعدي","en":"Al-Sa'di: then He said 'and establish prayer'; He did not say 'perform prayer' or 'come with prayer', because merely doing its outer form is not enough; establishing it is outward, by completing its pillars, obligations and conditions, and inward, by establishing its soul, which is presence of the heart and reflecting on what one says and does; this is the prayer of which Allah said 'prayer prevents indecency and wrongdoing' and which brings reward, for a servant gets from his prayer only what he understands of it."}]},{"id":"birr","ch":"mutaqin","t":"«ليس البر أن تولوا وجوهكم»: أركان البر وصفات الصادقين المتقين","e":"تفصيل البر في الإيمان والإنفاق وإقامة الصلاة والزكاة والوفاء بالعهد والصبر.","ay":[[2,177,177]],"q":[{"bk":"saadi","s":2,"ay":177,"x":"{ولكن البر من آمن بالله}؛ أي: بأنه إله واحد موصوف بكل صفة كمال منزَّه عن كلِّ نقص {واليوم الآخر}؛ وهو كل ما أخبر الله به في كتابه أو أخبر به الرسول مما يكون بعد الموت …","w":"السعدي","en":"Al-Sa'di: 'but righteousness is one who believes in Allah', meaning that He is one God, described with every attribute of perfection and free of every defect, 'and the Last Day', which is everything Allah or the Messenger told of what comes after death, 'and the angels' whom Allah described to us in His book and His Messenger described, 'and the Book', meaning the kinds of books Allah sent down to His messengers, the greatest of which is the Quran, so he believes in what it contains of reports and rulings ..."},{"bk":"saadi","s":2,"ay":177,"x":"أي: الفقر لأن الفقير يحتاج إلى الصبر من وجوه كثيرة لكونه يحصل له من الآلام القلبية والبدنية المستمرة ما لا يحصل لغيره، فإن تنعم الأغنياء بما لا يقدر عليه تألم وإن جاع أو جاعت عياله تألم، وإن أكل طعاماً غير موافق لهواه تألم، وإن عري أو كاد تألم، وإن نظر إلى ما بين يديه وما يتوهمه من المستقبل الذي يستعد له تألم، وإن أصابه البرد الذي لا يقدر على دفعه تألم، فكل هذه ونحوها مصائب يؤمر بالصبر عليها والاحتساب ورجاء الثواب من الله عليها …","w":"السعدي","en":"Al-Sa'di: poverty, because the poor person needs patience in many ways since he suffers continuous pains of the heart and body that others do not; if the wealthy enjoy what he cannot afford he is pained, if he or his family are hungry he is pained, if he eats food not to his liking, or is without clothes, or looks at what is before him and the future he fears, or is struck by cold he cannot ward off, he is pained; all of these are afflictions he is commanded to bear patiently, seeking reward and hoping for Allah's recompense for them …"},{"bk":"ibnkathir","s":2,"ay":177,"x":"وَقَوْلُهُ: ﴿أُولَئِكَ الَّذِينَ صَدَقُوا﴾ أَيْ: هَؤُلَاءِ الَّذِينَ اتَّصَفُوا بِهَذِهِ الصِّفَاتِ هُمُ الَّذِينَ صَدَقوا فِي إِيمَانِهِمْ؛ لِأَنَّهُمْ حَقَّقُوا الْإِيمَانَ الْقَلْبِيَّ بِالْأَقْوَالِ وَالْأَفْعَالِ، فَهَؤُلَاءِ هُمُ الَّذِينَ صَدَقُوا ﴿وَأُولَئِكَ هُمُ الْمُتَّقُونَ﴾ لِأَنَّهُمُ اتَّقَوُا الْمَحَارِمَ وَفَعَلُوا الطَّاعَاتِ.","w":"ابن كثير","en":"Ibn Kathir: 'those are the ones who have been true' means those described with these qualities are the ones who were true in their faith, because they realized faith of the heart in words and deeds; 'and those are the God-fearing' because they feared the forbidden and did acts of obedience."}]},{"id":"imran133","ch":"mutaqin","t":"«جنة عرضها السماوات والأرض أعدت للمتقين»: الإنفاق وكظم الغيظ والعفو والاستغفار","e":"وصف المتقين بالإنفاق في السراء والضراء وكظم الغيظ والعفو والاستغفار وعدم الإصرار على الذنب.","ay":[[3,133,136]],"q":[{"bk":"saadi","s":3,"ay":134,"x":"ثم وصف المتقين وأعمالهم فقال: {الذين ينفقون في السراء والضراء}؛ أي: في حال عسرهم ويسرهم إن أيسروا أكثروا من النفقة وإن أعسروا لم يحتقروا من المعروف شيئاً ولو قل، {والكاظمين الغيظ}: أي: إذا حصل لهم من غيرهم أذية توجب غيظهم، وهو امتلاء قلوبهم من الحنق الموجب للانتقام بالقول والفعل.","w":"السعدي","en":"Al-Sa'di: then He described the God-fearing and their deeds: 'those who spend in ease and hardship' means in their hardship and their ease; if they are well off they spend much, and if in hardship they do not belittle any good, however small; 'and those who restrain anger' means when they are harmed by others in a way that angers them, which is their hearts filling with rage that urges revenge in word and deed."},{"bk":"saadi","s":3,"ay":135,"x":"ثم ذكر اعتذارهم لربهم من جناياتهم وذنوبهم فقال: {135}{والذين إذا فعلوا فاحشة أو ظلموا أنفسهم}؛ أي: صدر منهم أعمال سيئة كبيرة أو ما دون ذلك، بادروا إلى التوبة والاستغفار، وذكروا ربهم وما توعد به العاصين، ووعد به المتقين فسألوه المغفرة لذنوبهم، والستر لعيوبهم، مع إقلاعهم عنها وندمهم عليها، فلهذا قال:{ولم يصروا على ما فعلوا وهم يعلمون}.","w":"السعدي","en":"Al-Sa'di: then He mentions their apology to their Lord for their offenses and sins: 'those who, when they commit an immorality or wrong themselves', meaning a great bad deed or lesser, hasten to repent and seek forgiveness, remember their Lord and what He threatened the disobedient with and promised the God-fearing, and ask Him to forgive their sins and cover their faults, while stopping and regretting; so He said: 'and do not persist in what they did while they know.'"}]},{"id":"imran15","ch":"mutaqin","t":"الصابرون والصادقون والقانتون والمستغفرون بالأسحار","e":"وصف المتقين بالصبر والصدق والقنوت والإنفاق والاستغفار بالأسحار.","ay":[[3,15,17]],"q":[{"bk":"saadi","s":3,"ay":17,"x":"ثم وصفهم بأجمل الصفات: بالصبر الذي هو حبس النفوس على ما يحبه الله طلباً لمرضاته، يصبرون على طاعة الله ويصبرون عن معاصيه ويصبرون على أقداره المؤلمة، وبالصدق بالأقوال والأحوال وهو استواء الظاهر والباطن وصدق العزيمة على سلوك الصراط المستقيم، وبالقنوت الذي هو دوام الطاعة مع مصاحبة الخشوع والخضوع، وبالنفقات في سبل الخيرات وعلى الفقراء وأهل الحاجات، وبالاستغفار خصوصاً وقت الأسحار، فإنهم مدوا الصلاة إلى وقت السحر؛ فجلسوا يستغفرون الله تعالى.","w":"السعدي","en":"Al-Sa'di: then He described them with the most beautiful qualities: patience, which is holding the soul to what Allah loves seeking His pleasure; they are patient in obeying Allah, patient away from His disobedience and patient with His painful decrees; truthfulness in words and states, which is the evenness of outward and inward and sincere resolve to walk the straight path; devotion, which is constant obedience with humility and submission; spending on paths of good and on the poor and needy; and seeking forgiveness, especially at dawn, for they extended their prayer until near dawn and sat seeking Allah's forgiveness."},{"bk":"ibnkathir","s":3,"ay":17,"x":"يَصِفُ تَعَالَى عِبَادَهُ الْمُتَّقِينَ الَّذِينَ وَعَدَهُمُ الثَّوَابَ الْجَزِيلَ، فَقَالَ تَعَالَى: ﴿الَّذِينَ يَقُولُونَ رَبَّنَا إِنَّنَا آمَنَّا﴾ أَيْ: بِكَ وَبِكِتَابِكَ وَبِرَسُولِكَ ﴿فَاغْفِرْ لَنَا ذُنُوبَنَا﴾ أَيْ بِإِيمَانِنَا بِكَ وَبِمَا شَرَعْتَهُ لَنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَتَقْصِيرَنَا مِنْ أَمْرِنَا بِفَضْلِكَ وَرَحْمَتِكَ ﴿وَقِنَا عَذَابَ النَّارِ﴾ ثُمَّ قَالَ: ﴿الصَّابِرِين﴾ أَيْ: فِي قِيَامِهِمْ بِالطَّاعَاتِ وَتَرْكِهِمُ الْمُحَرَّمَاتِ ﴿وَالصَّادِقِينَ﴾ فِيمَا أَخْبَرُوا بِهِ مِنْ إِيمَانِهِمْ بِمَا يَلْتَزِمُونَهُ مِنَ الْأَعْمَالِ الشَّاقَّةِ ﴿وَالقَانِتِينَ﴾ وَالْقُنُوتُ: الطَّاعَةُ وَالْخُضُوعُ ﴿والْمُنفِقِينَ﴾ أَيْ: مِنْ أَمْوَالِهِمْ فِي جَمِيعِ مَا أُمِرُوا بِهِ مِنَ الطَّاعَاتِ، وصلة الأرحام والقرابات، وَسَدِّ الخَلات، وَمُوَاسَاةِ ذَوِي الْحَاجَاتِ ﴿وَالْمُسْتَغْفِرِينَ بِالأسْحَارِ﴾ دَلَّ عَلَى فَضِيلَةِ الِاسْتِغْفَارِ وَقْتَ الْأَسْحَارِ.","w":"ابن كثير","en":"Ibn Kathir: Allah describes His God-fearing servants whom He promised great reward: 'who say: Our Lord, we have believed' in You, Your Book and Your Messenger, 'so forgive us our sins' by our faith and what You legislated, forgive our sins and shortcomings by Your favor and mercy, 'and protect us from the punishment of the Fire'; then 'the patient' in doing acts of obedience and leaving the forbidden, 'the truthful' in what they report of their faith and in the hard deeds they take on, 'the devout' in obedience and humility, 'those who spend' of their wealth in all that they were commanded of obedience, in keeping kinship, filling gaps and comforting the needy, 'and those who seek forgiveness before dawn', which shows the merit of seeking forgiveness at dawn."}]},{"id":"zumar33","ch":"mutaqin","t":"«والذي جاء بالصدق وصدّق به أولئك هم المتقون»","e":"مدح من جاء بالصدق وصدّق به ووصفه بالتقوى.","ay":[[39,33,35]],"q":[{"bk":"saadi","s":39,"ay":33,"x":"ولما ذَكَرَ الكاذبَ المكذِّب وجنايتَهُ وعقوبتَهُ؛ ذكر الصادقَ المصدِّقَ وثوابَه، فقال:{والذي جاء بالصِّدۡقِ}: في قوله وعمله، فدخل في ذلك الأنبياءُ ومَنْ قام مقامَهم ممن صَدَقَ فيما قاله عن خبرِ الله وأحكامِهِ، وفيما فَعَلَه من خصال الصدق، {وصَدَّقَ به}؛ أي: بالصدق؛ لأنَّه قد يجيء الإنسان بالصدق، ولكنْ قد لا يصدِّقُ به بسبب استكبارِهِ أو احتقارِهِ لمن قاله وأتى به؛ فلا بدَّ في المدح من الصدق والتصديق، فصدقُهُ يدلُّ على علمِهِ وعدلِهِ، وتصديقُهُ يدلُّ على تواضعه وعدم استكباره.","w":"السعدي","en":"Al-Sa'di: after mentioning the liar who denies and his crime and punishment, He mentions the truthful who affirms and his reward: 'the one who brings the truth' in his word and deed, which includes the prophets and those who stand in their place who spoke truly of Allah's reports and rulings and did the qualities of truthfulness, 'and believes in it', meaning in the truth, for a person may bring the truth yet not believe it because of arrogance or contempt for whoever brought it; so praise requires both truth and belief: his truthfulness shows his knowledge and fairness and his belief shows his humility and lack of arrogance."},{"bk":"ibnkathir","s":39,"ay":33,"x":"ثُمَّ قَالَ: ﴿وَالَّذِي جَاءَ بِالصِّدْقِ وَصَدَّقَ بِهِ﴾ قَالَ مُجَاهِدٌ، وَقَتَادَةُ، وَالرَّبِيعُ بْنُ أَنَسٍ، وَابْنُ زَيْدٍ: ﴿الَّذِي جَاءَ بِالصِّدْقِ﴾ هُوَ الرَّسُولُ. وَقَالَ السُّدِّيُّ: هُوَ جِبْرِيلُ عَلَيْهِ السَّلَامُ، ﴿وَصَدَّقَ بِهِ﴾ يَعْنِي: مُحَمَّدًا ﷺ. وَقَالَ عَلِيُّ بْنُ أَبِي طَلْحَةَ، عَنِ ابْنِ عَبَّاسٍ: ﴿وَالَّذِي جَاءَ بِالصِّدْقِ﴾ قَالَ: مَنْ جَاءَ بِلَا إِلَهَ إِلَّا اللَّهُ، ﴿وَصَدَّقَ بِهِ﴾ يَعْنِي: رَسُولَ اللَّهِ ﷺ. وَقَرَأَ الرَّبِيعُ بْنُ أَنَسٍ: \"الَّذِينَ جَاءُوا بِالصِّدْقِ\" يَعْنِي: الْأَنْبِيَاءَ، \"وَصَدَّقُوا بِهِ\" يَعْنِي: الْأَتْبَاعَ.","w":"ابن كثير","en":"Ibn Kathir: then He said: 'And the one who brought the truth and believed in it': Mujahid, Qatada, al-Rabi' ibn Anas and Ibn Zayd said that the one who brought the truth is the Messenger; al-Suddi said it is Jibril, and 'believed in it' means Muhammad …"}]},{"id":"dhariyat","ch":"mutaqin","t":"المحسنون: قليلاً من الليل ما يهجعون وفي أموالهم حق","e":"وصف المحسنين بقلة النوم والاستغفار بالأسحار وإعطاء السائل والمحروم من أموالهم.","ay":[[51,15,19]],"q":[{"bk":"saadi","s":51,"ay":17,"x":"ومن أفضل أنواع الإحسان في عبادة الخالق صلاةُ الليل الدالَّة على الإخلاص وتواطؤ القلب واللسان، ولهذا قال:{كانوا}؛ أي: المحسنون، {قليلاً من الليل ما يَهۡجَعونَ}؛ أي: كان هجوعهم؛ أي: نومهم بالليل قليلاً، وأمَّا أكثر الليل؛ فإنَّهم قانتون لربِّهم، ما بين صلاة وقراءة وذكر ودعاء وتضرُّع.","w":"السعدي","en":"Al-Sa'di: among the best kinds of good-doing in worshipping the Creator is night prayer, which shows sincerity and the agreement of heart and tongue; so He said: 'They used to sleep but little of the night', meaning their sleep at night was little; and most of the night they are devout to their Lord, between prayer, recitation, remembrance, supplication and pleading."},{"bk":"saadi","s":51,"ay":19,"x":"{وفي أموالهم حقٌّ}: واجبٌ ومستحبٌّ {للسائل والمحروم}؛ أي: للمحتاجين الذين يطلبون من الناس والذين لا يسألونهم.","w":"السعدي","en":"Al-Sa'di: 'and in their wealth is a right', obligatory and recommended, 'for the asker and the deprived', meaning the needy who ask people and those who do not ask them."}]},{"id":"sajda","ch":"mutaqin","t":"«تتجافى جنوبهم عن المضاجع»","e":"ترك المضاجع للدعاء خوفاً وطمعاً والإنفاق، وما أُخفي لهم من قرة أعين.","ay":[[32,15,17]],"q":[{"bk":"saadi","s":32,"ay":16,"x":"{تتجافى جُنوبهم عن المضاجِع}؛ أي: ترتفع جنوبُهم وتنزعجُ عن مضاجِعِها اللذيذِة إلى ما هو ألذُّ عندهم منه وأحبُّ إليهم، وهو الصلاة في الليل ومناجاة الله تعالى، ولهذا قال:{يَدۡعون ربَّهم}؛ أي: في جلب مصالِحِهم الدينيَّة والدنيويَّة ودفع مضارِّهما {خوفاً وطمعاً}؛ أي: جامعين بين الوصفينِ؛ خوفاً أن تُرَدَّ أعمالُهم، وطمعاً في قبولها؛ خوفاً من عذاب الله، وطمعاً في ثوابه، {وممَّا رزَقۡناهم}: من الرزق قليلاً أو كثيراً، {يُنفِقونَ}: ولم يذكُر قيد النفقة، ولا المنفَق عليه؛ ليدلَّ على العموم؛ فإنَّه يدخُلُ فيه النفقة الواجبة؛ كالزكوات والكفارات ونفقة الزوجات والأقارب، والنفقة المستحبَّة في وجوه الخير، والنفقة والإحسان المالي خيرٌ مطلقاً؛ سواء وافق فقيراً أو غنيًّا ، قريباً أو بعيداً، ولكن الأجر يتفاوت بتفاوتِ النفع، فهذا عملهم.","w":"السعدي","en":"Al-Sa'di: 'Their sides forsake their beds' means their sides rise and are disturbed from their pleasant beds toward what is more pleasant and dearer to them, which is night prayer and conversing with Allah; 'calling upon their Lord' for their religious and worldly good and to ward off harm, 'in fear and hope', combining both: fear that their deeds be rejected and hope that they be accepted, fear of Allah's punishment and hope for His reward; 'and spend from what We provided them', little or much, with no limit on the spending or on who receives it, to show it is general, covering obligatory spending such as zakat, expiations and maintenance of wives and relatives, and recommended spending in good causes; and money spent and kindness are good absolutely, to a poor or rich person, near or far, though reward differs with the benefit; this is their deed."},{"bk":"ibnkathir","s":32,"ay":16,"x":"ثُمَّ قَالَ [تَعَالَى: ﴿تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ﴾ يَعْنِي بِذَلِكَ: قِيَامَ اللَّيْلِ، وَتَرْكَ النَّوْمِ وَالِاضْطِجَاعِ عَلَى الْفُرَشِ الْوَطِيئَةِ.","w":"ابن كثير","en":"Ibn Kathir: then He said 'Their sides forsake their beds', meaning night prayer, and leaving sleep and lying on soft bedding."}]},{"id":"halu","ch":"maarij","t":"الإنسان خُلق هلوعاً إلا المصلين","e":"طبع الإنسان الهلوع واستثناء المصلين منه.","ay":[[70,19,23]],"q":[{"bk":"saadi","s":70,"ay":19,"x":"وهذا الوصف للإنسان من حيث هو؛ ووَصَفَ طبيعتَه [الأصليةَ] أنَّه هلوعٌ، وفسَّر الهَلوعَ بقوله:{إذا مسَّه الشَّرُّ جزوعاً}: فيجزع إن أصابه فقرٌ أو مرضٌ أو ذهابُ محبوبٍ له من مال أو أهل أو ولدٍ، ولا يستعمل في ذلك الصبر والرِّضا بما قضى الله، {وإذا مسَّه الخير منوعاً}: فلا يُنْفِقُ مما آتاه الله، ولا يشكر الله على نعمه وبرِّه فيجزع في الضَّراء ويمنع في السَّراء.","w":"السعدي","en":"Al-Sa'di: this describes the human being as such; He described his original nature as restless and explained restless by saying: 'when evil touches him, impatient', so he is anxious if poverty, illness or loss of something he loves in wealth, family or child befalls him and does not use patience and contentment with what Allah decreed; 'and when good touches him, withholding', so he does not spend of what Allah gave him nor thank Allah for His favors and kindness, so he is anxious in hardship and withholds in ease."},{"bk":"ibnkathir","s":70,"ay":19,"x":"يَقُولُ تَعَالَى مُخْبِرًا عَنِ الْإِنْسَانِ وَمَا هُوَ مَجْبُولٌ عَلَيْهِ مِنَ الْأَخْلَاقِ الدَّنِيئَةِ: ﴿إِنَّ الإنْسَانَ خُلِقَ هَلُوعًا﴾ ثُمَّ فَسَّرَهُ بِقَوْلِهِ: ﴿إِذَا مَسَّهُ الشَّرُّ جَزُوعًا﴾ أَيْ: إِذَا أَصَابَهُ الضُّرُّ فَزِعَ وَجَزِعَ وَانْخَلَعَ قَلْبُهُ مِنْ شِدَّةِ الرُّعْبِ، وَأَيِسَ أَنْ يَحْصُلَ لَهُ بَعْدَ ذَلِكَ خَيْرٌ.","w":"ابن كثير","en":"Ibn Kathir: Allah says, telling of the human being and the base character he is molded on: 'Indeed the human being was created restless', then explained it: 'when evil touches him, impatient', meaning when harm strikes him he is alarmed and frantic, his heart is torn from the force of terror, and he despairs of any good coming to him after it."}]},{"id":"maarij24","ch":"maarij","t":"صفات أهل المعارج: حق معلوم والتصديق بيوم الدين والإشفاق من العذاب","e":"الحق المعلوم في المال والتصديق بيوم الدين والإشفاق من عذاب الرب.","ay":[[70,24,28]],"q":[{"bk":"saadi","s":70,"ay":24,"x":"{والذين في أموالهم حقٌّ معلومٌ}: من زكاة وصدقة، {للسائل}: الذي يتعرَّض للسؤال، {والمحروم}: وهو المسكين الذي لا يسألُ الناس فيعطوه ولا يفطنُ له فيتصدَّق عليه.","w":"السعدي","en":"Al-Sa'di: 'and those in whose wealth is a known right', of zakat and charity, 'for the asker', who exposes himself to asking, 'and the deprived', who is the poor person who does not ask people, so they do not give him, nor is he noticed so as to be given charity."},{"bk":"saadi","s":70,"ay":26,"x":"{والذين يصدِّقون بيوم الدين}؛ أي: يؤمنون بما أخبر به وأخبرت به الرسلُ من الجزاء والبعث، ويتيقَّنون ذلك، فيستعدُّون للآخرة، ويَسْعَوْن لها سعيها.","w":"السعدي","en":"Al-Sa'di: 'and those who believe in the Day of Judgment' means they believe what Allah and the messengers told of recompense and resurrection, are certain of it, prepare for the Hereafter and strive for it as it deserves."}]},{"id":"maarij29","ch":"maarij","t":"حفظ الفروج والأمانة والشهادة والمحافظة على الصلاة","e":"رعاية الأمانات والعهود والقيام بالشهادات والمحافظة على الصلاة.","ay":[[70,29,35]],"q":[{"bk":"saadi","s":70,"ay":29,"x":"{والذين هم لأماناتهم وعهدِهِم راعونَ}؛ أي: مراعون لها حافظون مجتهدون على أدائها والوفاء بها، وهذا شاملٌ لجميع الأمانات التي بين العبد وبين ربِّه؛ كالتكاليف السِّرِّيَّة التي لا يطَّلع عليها إلاَّ اللهُ، والأمانات التي بيْن العبد وبيْن الخلق في الأموال والأسرار، وكذلك العهد شاملٌ للعهد الذي عاهد عليه الله، والعهد الذي عاهد الخلق عليه ؛ فإنَّ العهد يُسأل عنه العبد؛ هل قام به ووفَّاه أم رفضه وخانه فلم يقم به.","w":"السعدي","en":"Al-Sa'di: 'and those who are keepers of their trusts and their covenant' means they observe them, guard them and strive to deliver and fulfil them, and this includes all trusts between the servant and his Lord, such as hidden duties known only to Allah, and trusts between the servant and people in wealth and secrets; likewise the covenant includes the covenant made with Allah and the covenant made with people, for a servant is asked about the covenant, whether he kept and fulfilled it or rejected and betrayed it."},{"bk":"ibnkathir","s":70,"ay":33,"x":"وَقَوْلُهُ: ﴿وَالَّذِينَ هُمْ بِشَهَادَاتِهِمْ قَائِمُونَ﴾ أَيْ: مُحَافِظُونَ عَلَيْهَا لَا يَزِيدُونَ فِيهَا، وَلَا يَنْقُصُونَ مِنْهَا، وَلَا يَكْتُمُونَهَا، ﴿وَمَنْ يَكْتُمْهَا فَإِنَّهُ آثِمٌ قَلْبُهُ﴾ [الْبَقَرَةِ: ٢٨٣] .","w":"ابن كثير","en":"Ibn Kathir: 'and those who stand by their testimonies' means they keep them, neither adding to them nor reducing from them nor hiding them, 'and whoever conceals it, his heart is sinful.'"}]},{"id":"tawba112","ch":"tahim","t":"«التائبون العابدون الحامدون»: صفات المؤمنين المبايعين","e":"عدّ الصفات التسع للمؤمنين الذين اشترى الله منهم أنفسهم وأموالهم.","ay":[[9,112,112]],"q":[{"bk":"saadi","s":9,"ay":112,"x":"فقال: هم: {التائبون}؛ أي: الملازمون للتوبة في جميع الأوقات عن جميع السيئات. {العابدونَ}؛ أي: المتَّصفون بالعبوديَّة لله والاستمرار على طاعته من أداء الواجبات والمستحبَّات في كل وقتٍ؛ فبذلك يكون العبد من العابدين. {الحامدون}: لله في السرَّاء والضرَّاء واليسر والعسر، المعترفون بما لله عليهم من النعم الظاهرة والباطنة، المثنون على الله بذكرها وبذكره في آناء الليل وآناء النهار. {السائحون}: فسِّرت السياحة بالصيام، أو السياحة في طلب العلم، وفسِّرت بسياحة القلب في معرفة الله ومحبته والإنابة إليه على الدوام، والصحيح أنَّ المرادَ بالسياحة السفرُ في القُرُبات؛ كالحجِّ والعمرة والجهاد وطلب العلم وصلة الأقارب ونحو ذلك.","w":"السعدي","en":"Al-Sa'di: He said: they are 'the repentant', who keep repenting at all times from all sins; 'the worshippers', who are characterized by servitude to Allah and constant obedience, performing obligations and recommended acts at every time, which is how a servant becomes one of the worshippers; 'the praisers' of Allah in ease and hardship, acknowledging His outward and inward favors on them, praising Him by mentioning them and Him at both ends of the night and day; 'the travellers', where 'travelling' was explained as fasting, or travelling to seek knowledge, or the heart's journey in knowing Allah, loving Him and turning to Him always, and the correct view is that travelling here means journeying in acts of nearness such as Hajj, Umra, jihad, seeking knowledge, keeping kinship and the like."},{"bk":"ibnkathir","s":9,"ay":112,"x":"هَذَا نعتُ الْمُؤْمِنِينَ الَّذِينَ اشْتَرَى اللَّهُ مِنْهُمْ أَنْفُسَهُمْ وَأَمْوَالَهُمْ بِهَذِهِ الصِّفَاتِ الْجَمِيلَةِ وَالْخِلَالِ الْجَلِيلَةِ: ﴿التَّائِبُونَ﴾ مِنَ الذُّنُوبِ كُلِّهَا، التَّارِكُونَ لِلْفَوَاحِشِ، ﴿الْعَابِدُونَ﴾ أَيْ: الْقَائِمُونَ بِعِبَادَةِ رَبِّهِمْ مُحَافِظِينَ عَلَيْهَا، وَهِيَ الْأَقْوَالُ وَالْأَفْعَالُ فَمِنْ أخَصّ الْأَقْوَالِ الْحَمْدُ ؛ فَلِهَذَا قَالَ: ﴿الْحَامِدُونَ﴾ وَمِنْ أَفْضَلِ الْأَعْمَالِ الصيامُ، وَهُوَ تَرْكُ الملاذِّ مِنَ الطَّعَامِ وَالشَّرَابِ وَالْجِمَاعِ، وَهُوَ الْمُرَادُ بِالسِّيَاحَةِ هَاهُنَا؛ وَلِهَذَا قَالَ: ﴿السَّائِحُونَ﴾ كَمَا وَصَفَ أَزْوَاجَ النَّبِيِّ ﷺ بِذَلِكَ فِي قَوْلِهِ تَعَالَى: ﴿سَائِحَاتٍ﴾ [التَّحْرِيمِ: ٥] أَيْ: صَائِمَاتٍ، وَكَذَا الرُّكُوعُ وَالسُّجُودُ، وَهُمَا عِبَارَةٌ عَنِ الصَّلَاةِ، وَلِهَذَا قَالَ: ﴿الرَّاكِعُونَ السَّاجِدُونَ﴾ وَهُمْ مَعَ ذَلِكَ يَنْفَعُونَ خَلْقَ اللَّهِ، وَيُرْشِدُونَهُمْ إِلَى طَاعَةِ اللَّهِ بِأَمْرِهِمْ بِالْمَعْرُوفِ وَنَهْيِهِمْ عَنِ الْمُنْكَرِ، مَعَ الْعِلْمِ بِمَا يَنْبَغِي فِعْلُهُ وَيَجِبُ تركُه، وَهُوَ حِفْظُ حُدُودِ اللَّهِ فِي تَحْلِيلِهِ وَتَحْرِيمِهِ، عِلْمًا وَعَمَلًا فَقَامُوا بِعِبَادَةِ الْحَقِّ وَنُصْحِ الْخُلُقِ؛ وَلِهَذَا قَالَ …","w":"ابن كثير","en":"Ibn Kathir: this is the description of the believers from whom Allah bought their lives and wealth with these beautiful qualities: 'the repentant' from all sins, leaving indecencies; 'the worshippers' who keep up worship of their Lord, in words and deeds, and the most special of words is praise, so He said 'the praisers'; and among the best of deeds is fasting, which is leaving the pleasures of food, drink and intercourse, which is what is meant here by 'travelling', as He described the Prophet's wives as 'travelling' meaning fasting; likewise bowing and prostration, which stand for prayer, so He said 'the bowing, the prostrating'; and with that they benefit Allah's creation and guide them to obeying Him by enjoining what is right and forbidding what is wrong, with knowledge of what should and must be left, which is keeping the limits of Allah in what He made lawful and unlawful, in knowledge and action, so they established the worship of the Truth and sincere advice to creation; so He said …"}]},{"id":"ahzab35","ch":"tahim","t":"عشر صفات مشتركة للمؤمنين والمؤمنات","e":"الصفات العشر المشتركة للرجال والنساء من المسلمين والمؤمنين وما وعد الله به أهلها.","ay":[[33,35,35]],"q":[{"bk":"saadi","s":33,"ay":35,"x":"لما ذَكَرَ تعالى ثوابَ زوجاتِ الرسول - صلى الله عليه وسلم - وعقابهنَّ لو قُدِّرَ عدم الامتثال وأنَّه ليس مثلهنَّ أحدٌ من النساء؛ ذكر بقيَّة النساء غيرهنَّ، ولما كان حكمهنَّ والرجال واحداً؛ جعل الحكمَ مشتركاً، فقال:{إنَّ المسلمينَ والمسلماتِ}: وهذا في الشرائع الظاهرة إذا كانوا قائمين بها، {والمؤمنينَ والمؤمناتِ}: وهذا في الأمور الباطنة من عقائد القلب وأعماله، {والقانتينَ}؛ أي: المطيعين لله ولرسوله، {والقانتاتِ والصادقينَ}: في مقالهم وفعالهم، {والصادقاتِ والصابرينَ}: على الشدائد والمصائب، {والصابراتِ والخاشعين}: في جميع أحوالهم خصوصاً في عباداتهم ولا سيما في صلواتهم، {والخاشعاتِ والمتصدِّقين}: فرضاً ونفلاً، {والمتصدقاتِ والصائمينَ والصائماتِ}: شمل ذلك الفرض والنفل، {والحافظينَ فروجَهم}: عن الزنا ومقدِّماته، {والحافظات والذاكرينَ الله كثيراً}؛ أي: في أكثر الأوقات، خصوصاً في أوقات الأوراد المقيَّدة؛ كالصباح والمساء، وأدبار الصلوات المكتوبات …","w":"السعدي","en":"Al-Sa'di: after He mentioned the reward of the Prophet's wives and their punishment were they not to comply, and that no woman is like them, He mentioned the rest of the women; since their ruling and that of men is one, He made the ruling shared: 'Indeed the Muslim men and women', which is in the outward rulings when they uphold them, 'and the believing men and women', which is in the inner matters of heart beliefs and deeds, 'the devout' who obey Allah and His Messenger, 'the truthful' in word and deed, 'the patient' through hardships and afflictions, 'the humble' in all states especially in their worship and above all in prayer, 'the charitable' in obligatory and voluntary giving, 'the fasting men and women' covering obligatory and voluntary fasting, 'those who guard their chastity' from adultery and what leads to it, 'and those who remember Allah often' in most times, especially at fixed times of remembrance such as morning and evening and after the obligatory prayers …"},{"bk":"ibnkathir","s":33,"ay":35,"x":"﴿وَالصَّابِرِينَ وَالصَّابِرَاتِ﴾ : هَذِهِ سَجِيّة الْأَثْبَاتِ، وَهِيَ الصَّبْرُ عَلَى الْمَصَائِبِ، وَالْعِلْمُ بِأَنَّ الْمَقْدُورَ كَائِنٌ لَا مَحَالَةَ، وَتَلَقّي ذَلِكَ بِالصَّبْرِ وَالثَّبَاتِ، وَإِنَّمَا الصَّبْرُ عِنْدَ الصَّدْمَةِ الْأُولَى، أَيْ: أَصْعَبُهُ فِي أَوَّلِ وَهْلَةٍ، ثُمَّ مَا بَعْدَهُ أَسْهَلُ مِنْهُ، وَهُوَ صِدْقُ السَّجِيَّةِ وَثَبَاتُهَا.","w":"ابن كثير","en":"Ibn Kathir: 'the patient men and women': this is the nature of the steady; it is patience in affliction, knowing that what is decreed will certainly happen and meeting it with patience and firmness; patience is only at the first shock, meaning it is hardest at the very beginning and what follows is easier; it is truthfulness of nature and its steadiness."}]},{"id":"insan","ch":"tahim","t":"الأبرار: الوفاء بالنذر وإطعام الطعام لوجه الله","e":"وصف الأبرار بالوفاء بالنذر وخوف يوم الشر وإطعام الطعام على حبه لوجه الله.","ay":[[76,5,10]],"q":[{"bk":"saadi","s":76,"ay":7,"x":"ثم ذكر جملةً من أعمالهم ، فقال:{يوفون بالنَّذۡرِ}؛ أي: بما ألزموا به أنفسهم للَّه من النذور والمعاهدات، وإذا كانوا يوفون بالنذر الذي هو غير واجبٍ في الأصل عليهم إلا بإيجابهم على أنفسهم؛ كان فعلُهم وقيامهم بالفروض الأصليَّة من باب أولى وأحرى، {ويخافون يوماً كان شَرُّه مستطيراً}؛ أي: فاشياً منتشراً، فخافوا أن ينالهم شرُّه، فتركوا كلَّ سببٍ موجبٍ لذلك.","w":"السعدي","en":"Al-Sa'di: then He mentioned some of their deeds: 'they fulfil vows', meaning what they bound themselves to for Allah of vows and covenants; and if they fulfil a vow which was not obligatory for them except because they made it obligatory on themselves, then their doing the original obligations is more fitting; 'and they fear a Day whose evil will be widespread', meaning spreading everywhere; they feared that its evil would reach them, so they left every cause that leads to it."},{"bk":"saadi","s":76,"ay":9,"x":"{ويطعِمونَ الطَّعامَ على حبِّه}؛ أي: وهم في حال يحبُّون فيها المال والطعام، لكنَّهم قدَّموا محبَّة الله على محبَّة نفوسهم، ويتحرَّوْن في إطعامهم أولى الناس وأحوجَهم، {مسكيناً ويتيماً وأسيراً}: ويقصدون بإنفاقهم وإطعامهم وجهَ الله تعالى، ويقولون بلسان الحال:{إنَّما نطعِمُكم لوجه الله لا نريدُ منكم جزاءً ولا شكوراً}؛ أي: لا جزاءً ماليًّا ولا ثناءً قوليًّا، {إنا نخاف من ربِّنا يوماً عبوساً}؛ أي: شديد الجهمة والشرِّ، {قمطريراً}؛ أي: ضنكاً ضيقاً.","w":"السعدي","en":"Al-Sa'di: 'and they give food, despite loving it' means while they love wealth and food, yet they put love of Allah before love of themselves, and they seek the most deserving and needy people for their feeding, 'the poor, the orphan and the captive', and they intend by their spending and feeding the face of Allah, saying by the state of their heart: 'We feed you only for the face of Allah; we want from you neither reward nor thanks', meaning neither material repayment nor spoken praise; 'we fear from our Lord a Day austere', meaning grim and evil, 'distressing', meaning narrow and constricting."}]},{"id":"shura","ch":"tahim","t":"«وعلى ربهم يتوكلون» و«أمرهم شورى بينهم» والانتصار من البغي","e":"التوكل على الله، وكون أمرهم شورى بينهم، وحال الانتصار عند البغي.","ay":[[42,36,39]],"q":[{"bk":"saadi","s":42,"ay":36,"x":"ثم ذكر لمن هذا الثواب، فقال:{للذين آمنوا وعلى ربِّهم يتوكَّلونَ}؛ أي: جمعوا بين الإيمان الصحيح المستلزم لأعمال الإيمان الظاهرة والباطنة، وبين التوكُّل الذي هو الآلةُ لكلِّ عمل؛ فكلُّ عمل لا يَصْحَبُه التوكُّل؛ فغير تامٍّ، وهو الاعتماد بالقلب على الله في جَلْب ما يحبُّه العبد ودَفْع ما يكرهُهُ مع الثِّقة به تعالى.","w":"السعدي","en":"Al-Sa'di: then He mentions for whom this reward is: 'for those who believe and rely upon their Lord', meaning they combine sound faith, which requires the outward and inward deeds of faith, with reliance, which is the tool for every deed; for any deed not accompanied by reliance is incomplete, and reliance is the heart's dependence on Allah in bringing what the servant loves and repelling what he hates, with trust in Him."},{"bk":"saadi","s":42,"ay":38,"x":"أي: لا يستبدُّ أحدٌ منهم برأيه في أمر من الأمور المشتركة بينهم، وهذا لا يكون إلاَّ فرعاً عن اجتماعهم وتوالُفِهم وتوادُدِهم وتحابُبِهم؛ وكمال عقولهم أنَّهم إذا أرادوا أمراً من الأمور التي تحتاجُ إلى إعمال الفكرِ والرأي فيها؛ اجتمعوا لها وتشاوروا وبحثوا فيها، حتى إذا تبيَّنت لهم المصلحةُ؛ انتهزوها وبادروها، وذلك كالرأي في الغزو والجهاد وتولية الموظَّفين لإمارةٍ أو قضاءٍ أو غيره، وكالبحث في المسائل الدينيَّة عموماً؛ فإنَّها من الأمور المشتركة، والبحثُ فيها لبيان الصَّواب مما يحبُّه الله، وهو داخلٌ في هذه الآية.","w":"السعدي","en":"Al-Sa'di: 'consultation among them' means none of them dominates with his opinion in any shared matter, and this arises only from their unity, harmony, affection and love; and their perfect minds are shown when they want something requiring thought and opinion, they gather, consult and investigate it until the interest is clear, and then they seize it and hasten to it, such as opinion about war and jihad, appointing officials to rule or judge, and discussing religious matters in general, for they are shared matters and examining them to make the right view clear is something Allah loves, and it is included in this verse."}]},{"id":"lubb","ch":"tahim","t":"أولو الألباب: الوفاء بالعهد وصلة الرحم والخشية والصبر","e":"وصف أولي الألباب بالوفاء بعهد الله وصلة ما أمر الله به أن يوصل والخشية والصبر وإقامة الصلاة والإنفاق ودفع السيئة بالحسنة.","ay":[[13,19,24]],"q":[{"bk":"saadi","s":13,"ay":20,"x":"فإن سألتَ عن وصفِهم؛ فلا تجدُ أحسن من وصف الله لهم بقوله:{الذين يُوفونَ بعهدِ اللهِ}: الذي عَهِدَهُ إليهم والذي عاهدهم عليه من القيام بحقوقه كاملة موفرة؛ فالوفاء بها توفيتها حقَّها من التتميم لها والنصح فيها، ومن تمام الوفاء بها أنَّهم {لا ينقُضون الميثاقَ}؛ أي: العهد الذي عاهدوا الله عليه، فدخل في ذلك جميع المواثيق والعهود والأيمان والنُّذور التي يعقِدُها العباد، فلا يكون العبد من أولي الألباب الذين لهم الثواب العظيم إلا بأدائها كاملةً وعدم نقضها وبخسها.","w":"السعدي","en":"Al-Sa'di: if you ask about their description, you will find nothing better than Allah's description of them: 'those who fulfil the covenant of Allah', which He entrusted to them and made with them, to carry out His rights fully; fulfilling them is giving them their due by completing them and being sincere in them; and part of fulfilling it is that they 'do not break the pledge', meaning the covenant they made with Allah, which includes all pledges, covenants, oaths and vows that servants make, so a servant is not among those of understanding who have the great reward except by fulfilling them completely, not breaking them or cheating them."},{"bk":"saadi","s":13,"ay":22,"x":"{والذين صبروا}: على المأمورات بالامتثال، وعن المنهيَّات بالانكفاف عنها والبعد منها، وعلى أقدار الله المؤلمة بعدم تسخُّطها، ولكن بشرط أن يكون ذلك الصبر {ابتغاءَ وجهِ ربِّهم}: لا لغير ذلك من المقاصد والأغراض الفاسدة؛ فإنَّ هذا الصبر النافع، الذي يَحْبِسُ به العبد نفسه طلباً لمرضاة ربِّه ورجاءً للقرب منه والحظوة بثوابه، وهو الصبر الذي من خصائص أهل الإيمان، وأما الصبر المشترك الذي غايتُهُ التجلُّد ومنتهاه الفخر؛ فهذا يصدُرُ من البَرِّ والفاجر والمؤمن والكافر؛ فليس هو الممدوح على الحقيقة.","w":"السعدي","en":"Al-Sa'di: 'and those who are patient' in carrying out commands by doing them and away from prohibitions by abstaining and keeping far from them, and under Allah's painful decrees by not resenting them, on condition that this patience is 'seeking the face of their Lord', not for any other corrupt aims; for this is the beneficial patience by which a servant restrains himself seeking his Lord's pleasure, hoping for nearness to Him and His reward, and it is a patience peculiar to people of faith; as for common patience …"},{"bk":"ibnkathir","s":13,"ay":22,"x":"﴿وَالَّذِينَ صَبَرُوا ابْتِغَاءَ وَجْهِ رَبِّهِمْ﴾ أَيْ: عَنِ الْمَحَارِمِ وَالْمَآثِمِ، فَفَطَمُوا نُفُوسَهُمْ عَنْ ذَلِكَ لِلَّهِ عَزَّ وَجَلَّ؛ ابْتِغَاءَ مَرْضَاتِهِ وَجَزِيلِ ثَوَابِهِ ﴿وَأَقَامُوا الصَّلاةَ﴾ بِحُدُودِهَا وَمَوَاقِيتِهَا وَرُكُوعِهَا وَسُجُودِهَا وَخُشُوعِهَا عَلَى الْوَجْهِ الشَّرْعِيِّ الْمَرْضِي، ﴿وَأَنْفَقُوا مِمَّا رَزَقْنَاهُمْ﴾ أَيْ: عَلَى الَّذِينَ يَجِبُ عَلَيْهِمُ الْإِنْفَاقُ لَهُمْ مِنْ زَوْجَاتٍ وَقَرَابَاتٍ وَأَجَانِبَ، مِنْ فُقَرَاءَ وَمَحَاوِيجَ وَمَسَاكِينَ، ﴿سِرًّا وَعَلانِيَةً﴾ أَيْ: فِي السِّرِّ وَالْجَهْرِ، لَمْ يَمْنَعْهُمْ مِنْ ذَلِكَ حَالٌ مِنَ الْأَحْوَالِ، فِي آنَاءِ اللَّيْلِ وَأَطْرَافِ النَّهَارِ، ﴿وَيَدْرَءُونَ بِالْحَسَنَةِ السَّيِّئَةَ﴾ أَيْ: يَدْفَعُونَ الْقَبِيحَ بِالْحَسَنِ، فَإِذَا آذَاهُمْ أَحَدٌ قَابَلُوهُ بِالْجَمِيلِ صَبْرًا وَاحْتِمَالًا وَصَفْحًا وَعَفْوًا، كَمَا قَالَ تَعَالَى: ﴿ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ فَإِذَا الَّذِي بَيْنَكَ وَبَيْنَهُ عَدَاوَةٌ كَأَنَّهُ وَلِيٌّ حَمِيمٌ وَمَا يُلَقَّاهَا إِلا الَّذِينَ صَبَرُوا وَمَا يُلَقَّاهَا إِلا ذُو حَظٍّ عَظِيمٍ﴾ [فُصِّلَتْ: ٣٤، ٣٥] …","w":"ابن كثير","en":"Ibn Kathir: 'and those who are patient, seeking the face of their Lord' means from the forbidden and sins, so they restrained themselves from that for Allah seeking His pleasure and His great reward; 'and establish prayer' with its limits, times, bowing, prostration and humility in the lawful, pleasing manner; 'and spend from what We provided them' on those for whom spending is obligatory, wives and relatives, and on others, the poor, needy and destitute; 'secretly and openly' so that no state prevented them from that, in the hours of the night and the ends of the day; 'and repel evil with good' meaning they repel the ugly with the beautiful, so when someone harms them they meet him with kindness, patience, forbearance and pardon …"}]},{"id":"hadid16","ch":"qalb","t":"«ألم يأن للذين آمنوا أن تخشع قلوبهم»","e":"عتاب المؤمنين على عدم خشوع قلوبهم لذكر الله وما نزل من الحق.","ay":[[57,16,16]],"q":[{"bk":"saadi","s":57,"ay":16,"x":"لما ذكر حال المؤمنين والمؤمنات والمنافقين والمنافقات في الدار الآخرة؛ كان ذلك مما يدعو القلوب إلى الخشوع لربِّها والاستكانة لعظمته، فعاتب الله المؤمنين على عدم ذلك، فقال:{ألم يأنِ للذين آمنوا أن تَخۡشَعَ قلوبُهم لذِكۡرِ الله وما نَزَلَ من الحقِّ}؛ أي: ألم يأتِ الوقتُ الذي به تلينُ قلوبهم وتخشعُ لذِكْر الله الذي هو القرآن وتنقادُ لأوامره وزواجره وما نَزَلَ من الحقِّ الذي جاء به محمدٌ - صلى الله عليه وسلم -، وهذا فيه الحثُّ على الاجتهاد على خشوع القلب لله تعالى ولما أنزله من الكتاب والحكمة، وأن يتذكَّر المؤمنون المواعظ الإلهيَّة والأحكام الشرعيَّة كلَّ وقت ويحاسبوا أنفسَهم على ذلك، {ولا يكونوا كالذين أوتوا الكتاب من قَبۡلُ فطال عليهم الأمدُ}؛ أي …","w":"السعدي","en":"Al-Sa'di: after mentioning the state of the believing men and women and the hypocritical men and women in the Hereafter, which calls hearts to humility before their Lord and submission to His greatness, Allah rebuked the believers for lacking it, saying: 'Has the time not come for those who believe that their hearts should be humbled at the remembrance of Allah and what has come down of the truth?' meaning, has the time not come when their hearts soften and are humbled at remembrance of Allah, which is the Quran, and submit to its commands and prohibitions and to the truth that Muhammad brought; and this urges striving for the heart's humility before Allah and before what He sent down of the Book and wisdom, and that believers recall divine admonitions and legal rulings all the time and hold themselves to account for them, 'and not be like those who were given the Scripture before, and the time grew long for them' …"},{"bk":"ibnkathir","s":57,"ay":16,"x":"يَقُولُ اللَّهُ تَعَالَى: أَمَا آنَ لِلْمُؤْمِنِينَ أَنْ تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللَّهِ، أَيْ: تَلِينَ عِنْدَ الذِّكْرِ وَالْمَوْعِظَةِ وَسَمَاعِ الْقُرْآنِ، فَتَفْهَمَهُ وتنقادُ لَهُ وَتَسْمَعَ لَهُ وَتُطِيعَهُ.","w":"ابن كثير","en":"Ibn Kathir: Allah says: has the time not come for the believers that their hearts be humbled at the remembrance of Allah, meaning soften at remembrance, admonition and hearing the Quran, so they understand it, submit to it, listen to it and obey it."}]},{"id":"zumar23","ch":"qalb","t":"اقشعرار الجلود ولين القلوب عند ذكر الله","e":"اقشعرار جلود الذين يخشون ربهم ثم لينها ولين قلوبهم عند ذكر الله.","ay":[[39,23,23]],"q":[{"bk":"saadi","s":39,"ay":23,"x":"ولما كان القرآنُ العظيمُ بهذه الجلالة والعظمةِ؛ أثَّر في قلوب أولي الألباب المهتدين؛ فلهذا قال تعالى:{تَقۡشَعِرُّ منه جلودُ الذين يَخۡشَوۡنَ ربَّهم}: لما فيه من التخويف والترهيب المزعج، {ثمَّ تَلينُ جلودُهم وقلوبُهم إلى ذِكۡرِ اللَّهِ}؛ أي: عند ذكر الرجاء والترغيب؛ فهو تارةً يرغِّبُهم لعمل الخير، وتارةً يرهِّبُهم من عمل الشر.","w":"السعدي","en":"Al-Sa'di: since the great Quran is of such majesty and greatness, it affects the hearts of the guided people of understanding; so Allah said: 'the skins of those who fear their Lord shiver from it', from the alarming warning and threat in it, 'then their skins and hearts soften at the remembrance of Allah', meaning at mention of hope and encouragement; at times it encourages them to do good and at times warns them from doing evil."},{"bk":"ibnkathir","s":39,"ay":23,"x":"وَقَوْلُهُ: ﴿تَقْشَعِرُّ مِنْهُ جُلُودُ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَى ذِكْرِ اللَّهِ﴾ أَيْ هَذِهِ صِفَةُ الْأَبْرَارِ، عِنْدَ سَمَاعِ كَلَامِ الْجَبَّارِ، الْمُهَيْمِنِ الْعَزِيزِ الْغَفَّارِ، لِمَا يَفْهَمُونَ مِنْهُ مِنَ الْوَعْدِ وَالْوَعِيدِ.","w":"ابن كثير","en":"Ibn Kathir: 'the skins of those who fear their Lord shiver from it, then their skins and hearts soften at the remembrance of Allah' means this is the quality of the righteous when they hear the speech of the Almighty, the Guardian, the Mighty, the Forgiving, because of the promise and the warning they understand from it."}]},{"id":"rad28","ch":"qalb","t":"«ألا بذكر الله تطمئن القلوب»","e":"اطمئنان قلوب المؤمنين بذكر الله.","ay":[[13,28,29]],"q":[{"bk":"saadi","s":13,"ay":28,"x":"ثم ذكر تعالى علامة المؤمنين، فقال:{الذين آمنوا وتطمئنُّ قلوبُهم بذكر الله}؛ أي: يزول قلقها واضطرابها، وتحضُرُها أفراحها ولذَّاتها.","w":"السعدي","en":"Al-Sa'di: then Allah mentions a sign of the believers, saying: 'those who believe and whose hearts find rest in the remembrance of Allah' means their anxiety and unrest leave, and its joys and pleasures come to it."},{"bk":"ibnkathir","s":13,"ay":28,"x":"﴿الَّذِينَ آمَنُوا وَتَطْمَئِنُّ قُلُوبُهُمْ بِذِكْرِ اللَّهِ﴾ أَيْ: تَطِيبُ وَتَرْكَنُ إِلَى جَانِبِ اللَّهِ، وَتَسْكُنُ عِنْدَ ذِكْرِهِ، وَتَرْضَى بِهِ مَوْلًى وَنَصِيرًا؛ وَلِهَذَا قَالَ: ﴿أَلا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ﴾ أَيْ: هُوَ حَقِيقٌ بِذَلِكَ.","w":"ابن كثير","en":"Ibn Kathir: 'those who believe and whose hearts find rest in the remembrance of Allah' means they become good and rely on Allah, calm at His mention and content with Him as Lord and helper; so He said: 'Verily in the remembrance of Allah do hearts find rest', meaning it is truly fitting for that."}]},{"id":"fikr","ch":"qalb","t":"التفكر في خلق السماوات والأرض وذكر الله قياماً وقعوداً","e":"وصف أولي الألباب بذكر الله على كل حال والتفكر في خلق السماوات والأرض.","ay":[[3,190,191]],"q":[{"bk":"saadi","s":3,"ay":191,"x":"ثم وصف أولي الألباب بأنهم: {يذكرون الله} في جميع أحوالهم {قياماً وقعوداً وعلى جنوبهم}، وهذا يشمل جميع أنواع الذكر بالقول والقلب، ويدخل في ذلك الصلاة قائماً، فإن لم يستطع فقاعداً، فإن لم يستطع فعلى جنب، وأنهم:{يتفكرون في خلق السموات والأرض}؛ أي: ليستدلوا بها على المقصود منها، ودل هذا على أن التفكر عبادة من صفات أولياء الله العارفين، فإذا تفكروا بها عرفوا أن الله لم يخلقها عبثاً فيقولون:{ربنا ما خلقت هذا باطلاً سبحانك} عن كل ما لا يليق بجلالك بالحق وللحق بل خلقتها مشتملة على الحق {فقنا عذاب النار}، بأن تعصمنا من السيئات وتوفقنا للأعمال الصالحات لننال بذلك النجاة من النار.","w":"السعدي","en":"Al-Sa'di: then He described those of understanding as 'remembering Allah' in all their states, 'standing, sitting and on their sides', which includes every kind of remembrance by word and heart, including prayer standing, then sitting if unable, then on the side if unable; and 'reflecting on the creation of the heavens and the earth' to infer from them their purpose, which shows reflection is worship and a quality of Allah's knowing friends; when they reflect they know Allah did not create them in vain, so they say 'Our Lord, You did not create this in vain; glory be to You' above all that is unfitting for Your majesty, 'so protect us from the punishment of the Fire' by protecting us from sins and enabling us to do good works so that we are saved from the Fire."},{"bk":"ibnkathir","s":3,"ay":191,"x":"ثُمَّ وَصَفَ تَعَالَى أُولِي الْأَلْبَابِ فَقَالَ: ﴿الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِهِمْ﴾ كَمَا ثَبَتَ فِي صَحِيحِ الْبُخَارِيِّ عَنْ عِمْران بْنِ حُصَين، رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: \"صَلِّ قَائِمًا، فَإِنْ لَمْ تَسْتَطِعْ فَقَاعِدًا، فَإِنْ لَم تَسْتَطِعْ فَعَلَى جَنْبِكَ أَيْ: لَا يَقْطَعُونَ ذِكْره فِي جَمِيعِ أَحْوَالِهِمْ بِسَرَائِرِهِمْ وَضَمَائِرِهِمْ وَأَلْسِنَتِهِمْ ﴿وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالأرْضِ﴾ أَيْ: يَفْهَمُونَ مَا فِيهِمَا مِنَ الحكَم الدَّالَّةِ عَلَى عَظَمَةِ الْخَالِقِ وَقُدْرَتِهِ، وَعِلْمِهِ وَحِكْمَتِهِ، وَاخْتِيَارِهِ وَرَحْمَتِهِ.","w":"ابن كثير","en":"Ibn Kathir: then He described those of understanding: 'those who remember Allah standing, sitting and on their sides', as is established in Sahih al-Bukhari from Imran ibn Husayn that the Messenger of Allah said 'Pray standing; if you cannot, then sitting; if you cannot, then on your side'; meaning they do not cut off His remembrance in all their states, in their inner selves, hearts and tongues, 'and reflect on the creation of the heavens and the earth', meaning they understand the wisdom in them that points to the greatness of the Creator, His power, knowledge, wisdom, choice and mercy."}]},{"id":"habbaba","ch":"qalb","t":"«حبّب إليكم الإيمان وزيّنه في قلوبكم»","e":"تحبيب الإيمان وتزيينه في القلوب وتكريه الكفر والفسوق والعصيان.","ay":[[49,7,8]],"q":[{"bk":"saadi","s":49,"ay":7,"x":"أي: وليكن لديكم معلومًا أنَّ {رسول الله} - صلى الله عليه وسلم - بين أظهُرِكم، وهو الرسولُ الكريم البارُّ الراشدُ، الذي يريد بكم الخير، وينصح لكم، وتريدون لأنفسكم من الشرِّ والمضرَّة ما لا يوافقكم الرسولُ عليه، و {لو يطيعكم في كثيرٍ من الأمر} لشقَّ عليكم وأعنتكم، ولكن الرسول يرشدكُم، والله تعالى يحبِّب إليكم {الإيمان} ويزيِّنه {في قلوبكم} بما أودع في قلوبكم من محبة الحقِّ وإيثاره، وبما نصب على الحقِّ من الشواهد والأدلَّة الدالَّة على صحَّته وقبول القلوب والفِطَر له، وبما يفعله تعالى بكم من توفيقه للإنابة إليه، ويكرِّه {إليكم الكفر والفسوق}؛ أي: الذنوبَ الكبار.","w":"السعدي","en":"Al-Sa'di: know that the Messenger of Allah is among you, the noble, righteous, rightly guided Messenger who wants good for you and advises you, and you want for yourselves things of harm that the Messenger would not agree to; if he obeyed you in much of the matter you would be in difficulty and distress; but the Messenger guides you and Allah makes faith beloved to you and adorns it in your hearts through the love of truth and preference for it that He placed in your hearts, the evidences and proofs He set on the truth showing its soundness and the hearts' and natures' acceptance of it, and by His granting you success in turning to Him; and He makes disbelief and wrongdoing, meaning major sins, hateful to you."},{"bk":"ibnkathir","s":49,"ay":7,"x":"وَقَوْلُهُ: ﴿وَلَكِنَّ اللَّهَ حَبَّبَ إِلَيْكُمُ الإيمَانَ وَزَيَّنَهُ فِي قُلُوبِكُمْ﴾ أَيْ: حَبَّبَهُ إِلَى نُفُوسِكُمْ وَحَسَّنَهُ فِي قُلُوبِكُمْ.","w":"ابن كثير","en":"Ibn Kathir: 'but Allah has made faith beloved to you and adorned it in your hearts' means He made it beloved to your selves and made it beautiful in your hearts."}]},{"id":"sakina","ch":"qalb","t":"السكينة تنزل في قلوب المؤمنين فتزداد إيماناً","e":"إنزال السكينة في قلوب المؤمنين ليزدادوا إيماناً مع إيمانهم.","ay":[[48,4,4]],"q":[{"bk":"saadi","s":48,"ay":4,"x":"يخبر تعالى عن منَّته على المؤمنين بإنزال السكينة في قلوبهم، وهي السكونُ والطمأنينةُ والثباتُ عند نزول المحنِ المقلقةِ والأمور الصعبة التي تشوِّشُ القلوبَ وتزعجُ الألباب وتضعِفُ النفوس؛ فمن نعمة الله على عبده في هذه الحال أن يثبِّتَه ويربطَ على قلبه، وينزِلَ عليه السكينةَ، ليتلقَّى هذه المشقَّاتِ بقلبٍ ثابتٍ ونفس مطمئنةٍ، فيستعدَّ بذلك لإقامة أمر الله في هذه الحال، فيزداد بذلك إيمانُه، ويتمَّ إيقانُه.","w":"السعدي","en":"Al-Sa'di: Allah tells of His favor on the believers by sending down tranquillity in their hearts, which is calm, reassurance and steadfastness when worrying trials descend and hard matters that disturb hearts, trouble minds and weaken souls; part of Allah's favor on His servant in such a state is that He steadies him, binds his heart and sends down tranquillity on him, so he meets these hardships with a firm heart and a settled soul and is thereby prepared to carry out Allah's command in this state, so his faith increases and his certainty is completed."},{"bk":"ibnkathir","s":48,"ay":4,"x":"يَقُولُ تَعَالَى: ﴿هُوَ الَّذِي أَنزلَ السَّكِينَةَ﴾ أَيْ: جَعَلَ الطُّمَأْنِينَةَ.","w":"ابن كثير","en":"Ibn Kathir: Allah says: 'It is He who sent down tranquillity', meaning He made reassurance."}]},{"id":"ruhama","ch":"khuluq","t":"«رحماء بينهم»: الرحمة والتراحم بين المؤمنين","e":"وصف الذين مع الرسول بالشدة على الكفار والرحمة بينهم وكثرة الركوع والسجود.","ay":[[48,29,29]],"q":[{"bk":"saadi","s":48,"ay":29,"x":"يخبر تعالى عن رسوله محمد - صلى الله عليه وسلم - وأصحابه من المهاجرين والأنصار؛ أنَّهم بأكمل الصفات وأجلِّ الأحوال، وأنَّهم {أشداءُ على الكفَّارِ}؛ أي: جادِّين ومجتهدين في عداوتهم، وساعين في ذلك بغاية جهدهم، فلم يروا منهم إلاَّ الغلظةَ والشدَّةَ؛ فلذلك ذلَّ أعداؤُهم لهم وانكسروا وقهرهم المسلمون، {رحماءُ بينَهم}؛ أي: متحابُّون متراحمون متعاطفون كالجسد الواحد، يحبُّ أحدُهم لأخيه ما يحبُّ لنفسه، هذه معاملتُهم مع الخلق، وأمَّا معاملتُهم مع الخالق؛ فتراهم {رُكَّعاً سجداً}؛ أي: وصفهم كثرة الصلاة التي أجلُّ أركانها الركوع والسجود، {يبتغونَ}: بتلك العبادة {فضلاً من الله ورضواناً}؛ أي: هذا مقصودهم، بلوغُ رضا ربِّهم والوصول إلى ثوابِهِ {سيماهم في وجوهِهِم من أثرِ السُّجودِ}؛ أي: قد أثَّرت العبادة مِنْ كثرتِها وحسنِها في وجوههم حتى استنارتْ، لمَّا استنارت بالصلاة بواطنهم؛ استنارتْ ظواهِرُهم.","w":"السعدي","en":"Al-Sa'di: Allah tells of His Messenger Muhammad and his companions from the Muhajirun and Ansar that they have the most perfect qualities and noblest states: they are 'firm against the disbelievers', serious and striving in opposing them with all their effort, so the disbelievers saw from them only sternness and firmness, hence their enemies were humbled and broken and the Muslims overcame them; they are 'merciful among themselves', loving, compassionate and tender like one body, each loving for his brother what he loves for himself; this is their dealing with creation, while with the Creator you see them 'bowing and prostrating', meaning their description is much prayer whose greatest pillars are bowing and prostration, 'seeking bounty from Allah and pleasure', this is their aim, reaching their Lord's pleasure and His reward; 'their mark is on their faces from the trace of prostration', meaning worship, for its abundance and beauty, left a trace that lit up their faces; since their inner selves were lit by prayer, their outward appearance was lit."},{"bk":"ibnkathir","s":48,"ay":29,"x":"يُخْبِرُ تَعَالَى عَنْ مُحَمَّدٍ صَلَوَاتُ اللَّهِ عَلَيْهِ ، أَنَّهُ رَسُولُهُ حَقًّا بِلَا شَكٍّ وَلَا رَيْبٍ، فَقَالَ: ﴿مُحَمَّدٌ رَسُولُ اللَّهِ﴾ ، وَهَذَا مُبْتَدَأٌ وَخَبَرٌ، وَهُوَ مُشْتَمِلٌ عَلَى كُلِّ وَصْفٍ جَمِيلٍ، ثُمَّ ثَنَّى بِالثَّنَاءِ عَلَى أَصْحَابِهِ فَقَالَ: ﴿وَالَّذِينَ مَعَهُ أَشِدَّاءُ عَلَى الْكُفَّارِ رُحَمَاءُ بَيْنَهُمْ﴾ ، كَمَا قَالَ تَعَالَى: ﴿فَسَوْفَ يَأْتِي اللَّهُ بِقَوْمٍ يُحِبُّهُمْ وَيُحِبُّونَهُ أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ أَعِزَّةٍ عَلَى الْكَافِرِينَ﴾ [الْمَائِدَةِ: ٥٤] وَهَذِهِ صِفَةُ الْمُؤْمِنِينَ أَنْ يَكُونَ أَحَدُهُمْ شَدِيدًا عَنِيفًا عَلَى الْكَفَّارِ، رَحِيمًا بَرًّا بِالْأَخْيَارِ، غَضُوبًا عَبُوسًا فِي وَجْهِ الْكَافِرِ، ضَحُوكًا بَشُوشًا فِي وَجْهِ أَخِيهِ الْمُؤْمِنِ …","w":"ابن كثير","en":"Ibn Kathir: Allah tells that Muhammad is His Messenger truly, without doubt: 'Muhammad is the Messenger of Allah', which includes every beautiful description; then He followed with praise of his companions: 'and those with him are firm against the disbelievers, merciful among themselves', as He said: 'Allah will bring a people He loves and who love Him, humble toward the believers, firm against the disbelievers'; and this is the quality of the believers: each is firm and strict with the disbelievers, merciful and kind to the good, stern and frowning to the disbeliever, laughing and cheerful to his believing brother …"}]},{"id":"adhilla","ch":"khuluq","t":"«أذلة على المؤمنين أعزة على الكافرين»: محبة الله والجهاد","e":"صفة قوم يحبهم الله ويحبونه، أذلة على المؤمنين أعزة على الكافرين.","ay":[[5,54,54]],"q":[{"bk":"saadi","s":5,"ay":54,"x":"ومن صفاتهم أنهم:{أذلَّةٍ على المؤمنين أعزَّةٍ على الكافرين}؛ فهم للمؤمنين أذلَّة من محبتهم لهم ونُصحهم لهم ولينهم ورِفْقهم ورأفَتِهم ورحْمَتِهم بهم وسهولة جانبهم وقرب الشيء الذي يُطلب منهم، وعلى الكافرين بالله المعاندين لآياته المكذِّبين لرسُلِهِ أعزَّة، قد اجتمعت هممهم وعزائمهم على معاداتهم، وبذلوا جهدهم في كل سبب يحصل به الانتصار عليهم: قال تعالى: {وأعِدُّوا لهم ما استطعتُم من قُوَّةٍ ومن رِباط الخيل تُرهبونَ به عدَّو الله وعدوَّكم}.","w":"السعدي","en":"Al-Sa'di: and among their qualities is that they are 'humble toward the believers, firm against the disbelievers'; they are humble toward the believers from love for them, advising them, softness, gentleness, compassion and mercy toward them, being easy to approach and near to what they ask of them; and toward the disbelievers who deny Allah's verses and call His messengers liars, they are firm, their aspirations and resolve united against them, doing their utmost in every means by which victory over them is gained; Allah said: 'And prepare against them whatever you can of power and of tethered horses, to deter thereby the enemy of Allah and your enemy.'"},{"bk":"ibnkathir","s":5,"ay":54,"x":"وَقَوْلُهُ تَعَالَى: ﴿أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ أَعِزَّةٍ عَلَى الْكَافِرِينَ﴾ هَذِهِ صِفَاتُ الْمُؤْمِنِينَ الكُمَّل أَنْ يَكُونَ أَحَدُهُمْ مُتَوَاضِعًا لِأَخِيهِ وَوَلِيِّهِ، مُتَعَزِّزًا عَلَى خَصْمِهِ وَعَدُوِّهِ، كَمَا قَالَ تَعَالَى: ﴿مُحَمَّدٌ رَسُولُ اللَّهِ وَالَّذِينَ مَعَهُ أَشِدَّاءُ عَلَى الْكُفَّارِ رُحَمَاءُ بَيْنَهُمْ﴾ [الْفَتْحِ: ٢٩] .","w":"ابن كثير","en":"Ibn Kathir: 'humble toward the believers, firm against the disbelievers': these are the qualities of the perfect believers, that each be humble to his brother and friend, and strong against his adversary and enemy, as Allah said: 'Muhammad is the Messenger of Allah, and those with him are firm against the disbelievers, merciful among themselves.'"}]},{"id":"ahlkitab","ch":"khuluq","t":"أمة قائمة تتلو آيات الله وتأمر بالمعروف","e":"وصف أمة قائمة من أهل الكتاب بالإيمان بالله واليوم الآخر والأمر بالمعروف والمسارعة في الخيرات.","ay":[[3,113,115]],"q":[{"bk":"saadi","s":3,"ay":114,"x":"لما ذكر الله المنحرفين من أهل الكتاب بيَّن حالة المستقيمين منهم وأن منهم أمة مقيمون لأصول الدين وفروعه {يؤمنون بالله واليوم الآخر ويأمرون بالمعروف}؛ وهو الخير كله، وينهون عن المنكر وهو جميع الشر، كما قال تعالى:{ومن قوم موسى أمة يهدون بالحق وبه يعدلون}؛ و {يسارعون في الخيرات}؛ والمسارعة إلى الخيرات قدر زائد على مجرد فعلها، فهو وصف لهم بفعل الخيرات والمبادرة إليها وتكميلها بكل ما تتم به من واجب ومستحب.","w":"السعدي","en":"Al-Sa'di: after Allah mentioned the deviants among the People of the Book, He explained the state of the upright among them and that among them is a community that upholds the roots of religion and its branches: 'believing in Allah and the Last Day and enjoining what is right', which is all good, 'and forbidding what is wrong', which is all evil, as He said: 'And among the people of Moses is a community who guide by truth and by it act justly'; and 'they hasten to good deeds', and hastening to good is more than merely doing it: it is a description of doing good, hurrying to it and completing it with everything that perfects it of the obligatory and recommended."}]},{"id":"ithm","ch":"khuluq","t":"«والذين يجتنبون كبائر الإثم والفواحش وإذا ما غضبوا هم يغفرون»","e":"اجتناب كبائر الإثم والفواحش والمغفرة عند الغضب.","ay":[[42,37,37]],"q":[{"bk":"saadi","s":42,"ay":37,"x":"{والذين يَجتنبونَ كبائرَ الإثم والفواحشَ}: والفرق بين الكبائرِ والفواحشِ ـ مع أنَّ جميعَهما كبائرُ ـ أنَّ الفواحشَ هي الذُّنوب الكبارُ التي في النفوس داعٍ إليها كالزِّنا ونحوه، والكبائرُ ما ليس كذلك، هذا عند الاقتران، وأمَّا مع إفرادِ كلٍّ منهما عن الآخر؛ فإنَّ الآخر يدخُلُ فيه.","w":"السعدي","en":"Al-Sa'di: 'and those who avoid major sins and indecencies': the difference between major sins and indecencies, though both are major, is that indecencies are the great sins that the soul has an urge toward, such as adultery and the like, and major sins are what is not like that; this is when the two are mentioned together, but when each is mentioned alone the other is included in it."},{"bk":"ibnkathir","s":42,"ay":37,"x":"ثُمَّ قَالَ: ﴿وَالَّذِينَ يَجْتَنِبُونَ كَبَائِرَ الإثْمِ وَالْفَوَاحِشَ﴾ وَقَدْ قَدَّمْنَا الْكَلَامَ عَلَى الْإِثْمِ وَالْفَوَاحِشِ فِي \"سُورَةِ الْأَعْرَافِ\" ﴿وَإِذَا مَا غَضِبُوا هُمْ يَغْفِرُونَ﴾ أَيْ: سَجِيَّتُهُمْ [وَخَلْقُهُمْ وَطَبْعُهُمْ] تَقْتَضِي الصَّفْحَ وَالْعَفْوَ عَنِ النَّاسِ، لَيْسَ سَجِيَّتُهُمُ الِانْتِقَامَ مِنَ النَّاسِ.","w":"ابن كثير","en":"Ibn Kathir: then He said 'and those who avoid major sins and indecencies'; we have already discussed sin and indecencies in Surat al-A'raf; 'and when they are angry, they forgive' means their nature and disposition call for pardon and forgiveness toward people; revenge on people is not their nature."}]},{"id":"yunus62","ch":"thamarat","t":"أولياء الله لا خوف عليهم ولا هم يحزنون","e":"نفي الخوف والحزن عن أولياء الله وبيان صفتهم.","ay":[[10,62,64]],"q":[{"bk":"saadi","s":10,"ay":62,"x":"يخبر تعالى عن أوليائه وأحبائه ويذكر أعمالهم وأوصافهم وثوابهم، فقال:{ألا إنَّ أولياء الله لا خوفٌ عليهم}: فيما يستقبلونه مما أمامهم من المخاوف والأهوال، {ولا هم يحزنونَ}: على ما أسلفوا؛ لأنهم لم يسلِفوا إلاَّ صالح الأعمال، وإذا كانوا لا خوفٌ عليهم ولا هم يحزنون؛ ثبت لهم الأمنُ والسعادةُ والخير الكثير الذي لا يعلمه إلا الله تعالى.","w":"السعدي","en":"Al-Sa'di: Allah tells of His friends and beloved ones, and mentions their deeds, qualities and reward, saying: 'Indeed the friends of Allah, no fear is upon them' about what lies ahead of terrors and horrors, 'nor will they grieve' over what they sent ahead, because they sent ahead only righteous deeds; and if there is no fear on them and they do not grieve, then security, happiness and much good that only Allah knows are established for them."},{"bk":"ibnkathir","s":10,"ay":62,"x":"وَقَالَ عَبْدُ اللَّهِ بْنُ مَسْعُودٍ، وَابْنُ عَبَّاسٍ، وَغَيْرُ وَاحِدٍ مِنَ السَّلَفِ: أَوْلِيَاءُ اللَّهِ الَّذِينَ إِذَا رُءُوا ذُكِر اللَّهُ.","w":"ابن كثير","en":"Ibn Kathir: Abdullah ibn Mas'ud, Ibn Abbas and many of the early generations said: the friends of Allah are those who, when they are seen, Allah is remembered."}]},{"id":"istiqama","ch":"thamarat","t":"«الذين قالوا ربنا الله ثم استقاموا»: تنزل الملائكة وتبشرهم","e":"بشرى من قالوا ربنا الله ثم استقاموا بتنزل الملائكة عليهم.","ay":[[41,30,32]],"q":[{"bk":"saadi","s":41,"ay":30,"x":"يخبر تعالى عن أوليائِهِ، وفي ضمن ذلك تنشيطُهم والحثُّ على الاقتداء بهم، فقال:{إنَّ الذين قالوا ربُّنا الله ثم اسۡتَقاموا}؛ أي: اعترفوا ونطقوا ورَضُوا بربوبيَّة الله تعالى واستَسْلَموا لأمره، ثم استقاموا على الصراط المستقيم علماً وعملاً؛ فلهم البُشرى في الحياةِ الدُّنيا وفي الآخرة.","w":"السعدي","en":"Al-Sa'di: Allah tells of His friends, and within that encourages them and urges following them, saying: 'Indeed those who say: Our Lord is Allah, and then stand firm', meaning they acknowledged, spoke and accepted Allah's lordship and submitted to His command, then stood firm on the straight path in knowledge and deed; for them is good news in the life of this world and in the Hereafter."},{"bk":"ibnkathir","s":41,"ay":30,"x":"يَقُولُ تَعَالَى: ﴿إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا﴾ أَيْ: أَخْلَصُوا الْعَمَلَ لِلَّهِ، وَعَمِلُوا بِطَاعَةِ اللَّهِ تَعَالَى عَلَى مَا شَرَعَ اللَّهُ لَهُمْ.","w":"ابن كثير","en":"Ibn Kathir: Allah says: 'Indeed those who say: Our Lord is Allah, then stand firm', meaning they were sincere in deed for Allah and acted in obedience to Allah as He legislated for them."}]},{"id":"ankabut","ch":"thamarat","t":"الابتلاء سنة الله في المؤمنين ليتبين الصادق","e":"أن الابتلاء سنة جارية على من ادعى الإيمان ليتبين الصادق من الكاذب.","ay":[[29,2,3]],"q":[{"bk":"saadi","s":29,"ay":2,"x":"يخبر تعالى عن تمام حكمتِهِ، وأنَّ حكمته لا تقتضي أنَّ كلَّ مَنْ قال إنَّه مؤمنٌ وادَّعى لنفسه الإيمان؛ أن يَبْقَوا في حالة يَسْلَمون فيها من الفتن والمحن، ولا يَعْرِضُ لهم ما يشوِّش عليهم إيمانَهم وفروعه؛ فإنَّهم لو كان الأمر كذلك؛ لم يتميَّزِ الصادقُ من الكاذب والمحقُّ من المبطل …","w":"السعدي","en":"Al-Sa'di: Allah tells of the completeness of His wisdom, that His wisdom does not require everyone who says he is a believer and claims faith to remain in a state safe from trials and tests, with nothing arising to disturb their faith and its branches; for if it were so, the truthful would not be distinguished from the liar, nor the right from the false …"}]},{"id":"istikhlaf","ch":"thamarat","t":"وعد الاستخلاف والتمكين لمن آمن وعمل صالحاً","e":"وعد الله الذين آمنوا وعملوا الصالحات بالاستخلاف والتمكين وتبديل الخوف أمناً.","ay":[[24,55,55]],"q":[{"bk":"saadi","s":24,"ay":55,"x":"هذا من أوعاده الصادقةِ التي شوهِدَ تأويلُها ومَخْبَرُها؛ فإنَّه وعد مَنْ قام بالإيمان والعمل الصالح من هذه الأمة أن يَسْتَخْلِفَهم في الأرض، يكونونَ هم الخلفاءَ فيها، المتصرفين في تدبيرها، وأنه يمكِّن {لهم دينَهُمُ الذي ارتضى لهم}، وهو دينُ الإسلام الذي فاقَ الأديانَ كلَّها، ارتضاه لهذه الأمة لفضلِها وشرفِها ونعمتِهِ عليها بأن يتمكَّنوا من إقامتِهِ وإقامةِ شرائعِهِ الظاهرةِ والباطنةِ في أنفسهم وفي غيرِهم؛ لكونِ غيرِهم من أهل الأديان وسائرِ الكفَّار مغلوبينَ ذليلينَ، وأنَّه يبدِّلُهم [أمناً]{من بعدِ خوفِهم}؛ الذي كان الواحد منهم لا يتمكَّنُ من إظهار دينِهِ وما هو عليه إلاَّ بأذى كثيرٍ من الكفار، وكون جماعة المسلمين قليلينَ جدًّا بالنسبة إلى غيرهم، وقد رماهُم أهلُ الأرض عن قوسٍ واحدةٍ، وبَغَوْا لهم الغوائلَ، فوعَدَهم الله هذه الأمورَ وقت نزول الآية …","w":"السعدي","en":"Al-Sa'di: this is one of His true promises whose fulfilment has been seen and witnessed: He promised whoever establishes faith and righteous deeds among this nation that He would make them successors in the land, the ones who rule and manage it, and that He would establish for them their religion which He approved for them, which is Islam, which surpassed all religions, approved for this nation for its merit, honor and His favor on it, by letting them uphold it and its outward and inward laws in themselves and in others, since others of the religions and the rest of the disbelievers are defeated and humbled; and that He would change their fear into security, the fear in which one of them could not show his religion except with great harm from the disbelievers, when the Muslim community was very few compared to others and the people of the earth shot at them from one bow and plotted against them; so Allah promised them these things at the time the verse was revealed …"},{"bk":"ibnkathir","s":24,"ay":55,"x":"وَقَالَ الرَّبِيعِ بْنِ أَنَسٍ، عَنْ أَبِي الْعَالِيَةِ فِي قَوْلِهِ: ﴿وَعَدَ اللَّهُ الَّذِينَ آمَنُوا مِنْكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الأرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِنْ قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِي ارْتَضَى لَهُمْ وَلَيُبَدِّلَنَّهُمْ مِنْ بَعْدِ خَوْفِهِمْ أَمْنًا﴾ الْآيَةَ، قَالَ: كَانَ النَّبِيُّ ﷺ وَأَصْحَابُهُ بِمَكَّةَ نَحْوًا مِنْ عَشْرِ سِنِينَ، يَدْعُونَ إِلَى اللَّهِ وَحْدَهُ، وَعِبَادَتِهِ وَحْدَهُ لَا شَرِيكَ لَهُ سرًّا وَهُمْ خَائِفُونَ، لَا يُؤْمَرُونَ بِالْقِتَالِ، حَتَّى أُمِرُوا بعدُ بِالْهِجْرَةِ إِلَى الْمَدِينَةِ، فَقَدِمُوا الْمَدِينَةَ، فَأَمَرَهُمُ اللَّهُ بِالْقِتَالِ، فَكَانُوا بِهَا خَائِفِينَ يُمْسُون فِي السِّلَاحِ ويصبحون في السلاح، فَغَيَّرُوا بِذَلِكَ مَا شَاءَ اللَّهُ.","w":"ابن كثير","en":"Ibn Kathir: al-Rabi' ibn Anas reported from Abu al-Aliyah on His saying 'Allah has promised those among you who believe and do righteous deeds that He will surely make them successors in the land...' that the Prophet and his companions were in Mecca for about ten years calling to Allah alone and to worship Him alone with no partner, secretly and afraid, not commanded to fight, until they were commanded to migrate to Madina; they came to Madina and Allah commanded them to fight, and they were afraid there, spending evening and morning in arms; then with that Allah changed what He willed."}]},{"id":"tahinu","ch":"thamarat","t":"«ولا تهنوا ولا تحزنوا وأنتم الأعلون إن كنتم مؤمنين»","e":"تثبيت المؤمنين بعد الشدة ونهيهم عن الوهن والحزن وبيان علوهم بالإيمان.","ay":[[3,139,139]],"q":[{"bk":"saadi","s":3,"ay":139,"x":"يقول تعالى مشجعاً لعباده المؤمنين ومقوياً لعزائمهم ومنهضاً لهممهم: {ولا تهنوا ولا تحزنوا}؛ أي: ولا تهنوا وتضعفوا في أبدانكم، ولا تحزنوا في قلوبكم عندما أصابتكم المصيبة، وابتليتم بهذه البلوى، فإن الحزن في القلوب والوهن على الأبدان زيادة مصيبة عليكم، وعون لعدوكم عليكم بل شجعوا قلوبكم وصبروها وادفعوا عنها الحزن وتصلبوا على قتال عدوكم، وذكر تعالى أنه لا ينبغي ولا يليق بهم الوهن والحزن وهم الأعلون في الإيمان ورجاء نصر الله وثوابه، فالمؤمن المبتغي ما وعده الله من الثواب الدنيوي والأخروي لا ينبغي له ذلك، ولهذا قال تعالى:{وأنتم الأعلون إن كنتم مؤمنين}.","w":"السعدي","en":"Al-Sa'di: Allah says, encouraging His believing servants, strengthening their resolve and raising their aspirations: 'Do not weaken and do not grieve', meaning do not weaken in your bodies nor grieve in your hearts when affliction befell you and you were tried with this trial, for grief in hearts and weakness in bodies is an added affliction for you and help for your enemy against you; rather encourage your hearts, make them patient, drive grief away, and stand firm in fighting your enemy; and He mentioned that weakness and grief do not befit them since they are the uppermost in faith and in hoping for Allah's victory and reward, so the believer who seeks what Allah promised of worldly and Hereafter reward should not have them …"},{"bk":"ibnkathir","s":3,"ay":139,"x":"ثُمَّ قَالَ مُسَلِّيًا لِلْمُؤْمِنِينَ: ﴿وَلا تَهِنُوا﴾ أَيْ: لَا تَضعفوا بِسَبَبِ مَا جَرَى ﴿وَلا تَحْزَنُوا وَأَنْتُمُ الأعْلَوْنَ إِنْ كُنْتُمْ مُؤْمِنِينَ﴾ أَيِ: الْعَاقِبَةُ وَالنُّصْرَةُ لَكُمْ أَيُّهَا الْمُؤْمِنُونَ.","w":"ابن كثير","en":"Ibn Kathir: then He said, consoling the believers: 'Do not weaken', meaning do not become weak because of what happened, 'and do not grieve, for you are the superior if you are believers', meaning the outcome and victory are yours, O believers."}]}],"ay":{"8":"ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدٗى لِّلۡمُتَّقِينَ","9":"ٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","10":"وَٱلَّذِينَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ","11":"أُوْلَٰٓئِكَ عَلَىٰ هُدٗى مِّن رَّبِّهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","183":"۞ لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ","307":"۞ قُلۡ أَؤُنَبِّئُكُم بِخَيۡرٖ مِّن ذَٰلِكُمۡۖ لِلَّذِينَ ٱتَّقَوۡاْ عِندَ رَبِّهِمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَأَزۡوَٰجٞ مُّطَهَّرَةٞ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ","308":"ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ","309":"ٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلۡقَٰنِتِينَ وَٱلۡمُنفِقِينَ وَٱلۡمُسۡتَغۡفِرِينَ بِٱلۡأَسۡحَارِ","405":"۞ لَيۡسُواْ سَوَآءٗۗ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ وَهُمۡ يَسۡجُدُونَ","406":"يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ وَأُوْلَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ","407":"وَمَا يَفۡعَلُواْ مِنۡ خَيۡرٖ فَلَن يُكۡفَرُوهُۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ","425":"۞ وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ","426":"ٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ","427":"وَٱلَّذِينَ إِذَا فَعَلُواْ فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ لِذُنُوبِهِمۡ وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ يُصِرُّواْ عَلَىٰ مَا فَعَلُواْ وَهُمۡ يَعۡلَمُونَ","428":"أُوْلَٰٓئِكَ جَزَآؤُهُم مَّغۡفِرَةٞ مِّن رَّبِّهِمۡ وَجَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ","431":"وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ","482":"إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتٖ لِّأُوْلِي ٱلۡأَلۡبَٰبِ","483":"ٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِهِمۡ وَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا سُبۡحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ","722":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَن يَرۡتَدَّ مِنكُمۡ عَن دِينِهِۦ فَسَوۡفَ يَأۡتِي ٱللَّهُ بِقَوۡمٖ يُحِبُّهُمۡ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ يُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوۡمَةَ لَآئِمٖۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ","1161":"إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَٰتُهُۥ زَادَتۡهُمۡ إِيمَٰنٗا وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ","1162":"ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","1163":"أُوْلَٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُمۡ دَرَجَٰتٌ عِندَ رَبِّهِمۡ وَمَغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ","1346":"ٱلتَّٰٓئِبُونَ ٱلۡعَٰبِدُونَ ٱلۡحَٰمِدُونَ ٱلسَّٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ ٱلۡأٓمِرُونَ بِٱلۡمَعۡرُوفِ وَٱلنَّاهُونَ عَنِ ٱلۡمُنكَرِ وَٱلۡحَٰفِظُونَ لِحُدُودِ ٱللَّهِۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ","1425":"أَلَآ إِنَّ أَوۡلِيَآءَ ٱللَّهِ لَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","1426":"ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ","1427":"لَهُمُ ٱلۡبُشۡرَىٰ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۚ لَا تَبۡدِيلَ لِكَلِمَٰتِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","1725":"۞ أَفَمَن يَعۡلَمُ أَنَّمَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ كَمَنۡ هُوَ أَعۡمَىٰٓۚ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ","1726":"ٱلَّذِينَ يُوفُونَ بِعَهۡدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلۡمِيثَٰقَ","1727":"وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخۡشَوۡنَ رَبَّهُمۡ وَيَخَافُونَ سُوٓءَ ٱلۡحِسَابِ","1728":"وَٱلَّذِينَ صَبَرُواْ ٱبۡتِغَآءَ وَجۡهِ رَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ أُوْلَٰٓئِكَ لَهُمۡ عُقۡبَى ٱلدَّارِ","1729":"جَنَّٰتُ عَدۡنٖ يَدۡخُلُونَهَا وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۖ وَٱلۡمَلَٰٓئِكَةُ يَدۡخُلُونَ عَلَيۡهِم مِّن كُلِّ بَابٖ","1730":"سَلَٰمٌ عَلَيۡكُم بِمَا صَبَرۡتُمۡۚ فَنِعۡمَ عُقۡبَى ٱلدَّارِ","1734":"ٱلَّذِينَ ءَامَنُواْ وَتَطۡمَئِنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ","1735":"ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ طُوبَىٰ لَهُمۡ وَحُسۡنُ مَـَٔابٖ","2673":"قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ","2674":"ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ","2675":"وَٱلَّذِينَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ","2676":"وَٱلَّذِينَ هُمۡ لِلزَّكَوٰةِ فَٰعِلُونَ","2677":"وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ","2678":"إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ","2679":"فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡعَادُونَ","2680":"وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ","2681":"وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَوَٰتِهِمۡ يُحَافِظُونَ","2682":"أُوْلَٰٓئِكَ هُمُ ٱلۡوَٰرِثُونَ","2683":"ٱلَّذِينَ يَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ","2841":"إِنَّمَا كَانَ قَوۡلَ ٱلۡمُؤۡمِنِينَ إِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ أَن يَقُولُواْ سَمِعۡنَا وَأَطَعۡنَاۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","2842":"وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخۡشَ ٱللَّهَ وَيَتَّقۡهِ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ","2845":"وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَيَسۡتَخۡلِفَنَّهُمۡ فِي ٱلۡأَرۡضِ كَمَا ٱسۡتَخۡلَفَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَلَيُمَكِّنَنَّ لَهُمۡ دِينَهُمُ ٱلَّذِي ٱرۡتَضَىٰ لَهُمۡ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعۡدِ خَوۡفِهِمۡ أَمۡنٗاۚ يَعۡبُدُونَنِي لَا يُشۡرِكُونَ بِي شَيۡـٔٗاۚ وَمَن كَفَرَ بَعۡدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ","2852":"إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُواْ مَعَهُۥ عَلَىٰٓ أَمۡرٖ جَامِعٖ لَّمۡ يَذۡهَبُواْ حَتَّىٰ يَسۡتَـٔۡذِنُوهُۚ إِنَّ ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ أُوْلَٰٓئِكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦۚ فَإِذَا ٱسۡتَـٔۡذَنُوكَ لِبَعۡضِ شَأۡنِهِمۡ فَأۡذَن لِّمَن شِئۡتَ مِنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمُ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","2917":"وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا وَإِذَا خَاطَبَهُمُ ٱلۡجَٰهِلُونَ قَالُواْ سَلَٰمٗا","2918":"وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمۡ سُجَّدٗا وَقِيَٰمٗا","2919":"وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا","2920":"إِنَّهَا سَآءَتۡ مُسۡتَقَرّٗا وَمُقَامٗا","2921":"وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا","2922":"وَٱلَّذِينَ لَا يَدۡعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقۡتُلُونَ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا يَزۡنُونَۚ وَمَن يَفۡعَلۡ ذَٰلِكَ يَلۡقَ أَثَامٗا","2923":"يُضَٰعَفۡ لَهُ ٱلۡعَذَابُ يَوۡمَ ٱلۡقِيَٰمَةِ وَيَخۡلُدۡ فِيهِۦ مُهَانًا","2924":"إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلٗا صَٰلِحٗا فَأُوْلَٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمۡ حَسَنَٰتٖۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا","2925":"وَمَن تَابَ وَعَمِلَ صَٰلِحٗا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابٗا","2926":"وَٱلَّذِينَ لَا يَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّواْ بِٱللَّغۡوِ مَرُّواْ كِرَامٗا","2927":"وَٱلَّذِينَ إِذَا ذُكِّرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَمۡ يَخِرُّواْ عَلَيۡهَا صُمّٗا وَعُمۡيَانٗا","2928":"وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعۡيُنٖ وَٱجۡعَلۡنَا لِلۡمُتَّقِينَ إِمَامًا","2929":"أُوْلَٰٓئِكَ يُجۡزَوۡنَ ٱلۡغُرۡفَةَ بِمَا صَبَرُواْ وَيُلَقَّوۡنَ فِيهَا تَحِيَّةٗ وَسَلَٰمًا","2930":"خَٰلِدِينَ فِيهَاۚ حَسُنَتۡ مُسۡتَقَرّٗا وَمُقَامٗا","3341":"أَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ","3342":"وَلَقَدۡ فَتَنَّا ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُواْ وَلَيَعۡلَمَنَّ ٱلۡكَٰذِبِينَ","3517":"إِنَّمَا يُؤۡمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُواْ بِهَا خَرُّواْۤ سُجَّدٗاۤ وَسَبَّحُواْ بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا يَسۡتَكۡبِرُونَ۩","3518":"تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","3519":"فَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ","3555":"مِّنَ ٱلۡمُؤۡمِنِينَ رِجَالٞ صَدَقُواْ مَا عَٰهَدُواْ ٱللَّهَ عَلَيۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن يَنتَظِرُۖ وَمَا بَدَّلُواْ تَبۡدِيلٗا","3556":"لِّيَجۡزِيَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدۡقِهِمۡ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا","3567":"إِنَّ ٱلۡمُسۡلِمِينَ وَٱلۡمُسۡلِمَٰتِ وَٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ وَٱلۡقَٰنِتِينَ وَٱلۡقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ وَٱلصَّٰبِرَٰتِ وَٱلۡخَٰشِعِينَ وَٱلۡخَٰشِعَٰتِ وَٱلۡمُتَصَدِّقِينَ وَٱلۡمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلۡحَٰفِظِينَ فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرٗا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمٗا","3568":"وَمَا كَانَ لِمُؤۡمِنٖ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمۡرًا أَن يَكُونَ لَهُمُ ٱلۡخِيَرَةُ مِنۡ أَمۡرِهِمۡۗ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ ضَلَّ ضَلَٰلٗا مُّبِينٗا","4080":"ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبٗا مُّتَشَٰبِهٗا مَّثَانِيَ تَقۡشَعِرُّ مِنۡهُ جُلُودُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِينُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ ٱللَّهِۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٍ","4090":"وَٱلَّذِي جَآءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦٓ أُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ","4091":"لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ","4092":"لِيُكَفِّرَ ٱللَّهُ عَنۡهُمۡ أَسۡوَأَ ٱلَّذِي عَمِلُواْ وَيَجۡزِيَهُمۡ أَجۡرَهُم بِأَحۡسَنِ ٱلَّذِي كَانُواْ يَعۡمَلُونَ","4247":"إِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ تَتَنَزَّلُ عَلَيۡهِمُ ٱلۡمَلَٰٓئِكَةُ أَلَّا تَخَافُواْ وَلَا تَحۡزَنُواْ وَأَبۡشِرُواْ بِٱلۡجَنَّةِ ٱلَّتِي كُنتُمۡ تُوعَدُونَ","4248":"نَحۡنُ أَوۡلِيَآؤُكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَلَكُمۡ فِيهَا مَا تَشۡتَهِيٓ أَنفُسُكُمۡ وَلَكُمۡ فِيهَا مَا تَدَّعُونَ","4249":"نُزُلٗا مِّنۡ غَفُورٖ رَّحِيمٖ","4307":"فَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰ لِلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ","4308":"وَٱلَّذِينَ يَجۡتَنِبُونَ كَبَٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ وَإِذَا مَا غَضِبُواْ هُمۡ يَغۡفِرُونَ","4309":"وَٱلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","4310":"وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلۡبَغۡيُ هُمۡ يَنتَصِرُونَ","4586":"هُوَ ٱلَّذِيٓ أَنزَلَ ٱلسَّكِينَةَ فِي قُلُوبِ ٱلۡمُؤۡمِنِينَ لِيَزۡدَادُوٓاْ إِيمَٰنٗا مَّعَ إِيمَٰنِهِمۡۗ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا","4611":"مُّحَمَّدٞ رَّسُولُ ٱللَّهِۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلۡكُفَّارِ رُحَمَآءُ بَيۡنَهُمۡۖ تَرَىٰهُمۡ رُكَّعٗا سُجَّدٗا يَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗاۖ سِيمَاهُمۡ فِي وُجُوهِهِم مِّنۡ أَثَرِ ٱلسُّجُودِۚ ذَٰلِكَ مَثَلُهُمۡ فِي ٱلتَّوۡرَىٰةِۚ وَمَثَلُهُمۡ فِي ٱلۡإِنجِيلِ كَزَرۡعٍ أَخۡرَجَ شَطۡـَٔهُۥ فَـَٔازَرَهُۥ فَٱسۡتَغۡلَظَ فَٱسۡتَوَىٰ عَلَىٰ سُوقِهِۦ يُعۡجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلۡكُفَّارَۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ مِنۡهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمَۢا","4618":"وَٱعۡلَمُوٓاْ أَنَّ فِيكُمۡ رَسُولَ ٱللَّهِۚ لَوۡ يُطِيعُكُمۡ فِي كَثِيرٖ مِّنَ ٱلۡأَمۡرِ لَعَنِتُّمۡ وَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيۡكُمُ ٱلۡإِيمَٰنَ وَزَيَّنَهُۥ فِي قُلُوبِكُمۡ وَكَرَّهَ إِلَيۡكُمُ ٱلۡكُفۡرَ وَٱلۡفُسُوقَ وَٱلۡعِصۡيَانَۚ أُوْلَٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ","4619":"فَضۡلٗا مِّنَ ٱللَّهِ وَنِعۡمَةٗۚ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","4621":"إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ","4626":"إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمۡ يَرۡتَابُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِۚ أُوْلَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ","4689":"إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتٖ وَعُيُونٍ","4690":"ءَاخِذِينَ مَآ ءَاتَىٰهُمۡ رَبُّهُمۡۚ إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُحۡسِنِينَ","4691":"كَانُواْ قَلِيلٗا مِّنَ ٱلَّيۡلِ مَا يَهۡجَعُونَ","4692":"وَبِٱلۡأَسۡحَارِ هُمۡ يَسۡتَغۡفِرُونَ","4693":"وَفِيٓ أَمۡوَٰلِهِمۡ حَقّٞ لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ","5090":"۞ أَلَمۡ يَأۡنِ لِلَّذِينَ ءَامَنُوٓاْ أَن تَخۡشَعَ قُلُوبُهُمۡ لِذِكۡرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلۡحَقِّ وَلَا يَكُونُواْ كَٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلُ فَطَالَ عَلَيۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡۖ وَكَثِيرٞ مِّنۡهُمۡ فَٰسِقُونَ","5134":"وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِيمَٰنَ مِن قَبۡلِهِمۡ يُحِبُّونَ مَنۡ هَاجَرَ إِلَيۡهِمۡ وَلَا يَجِدُونَ فِي صُدُورِهِمۡ حَاجَةٗ مِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞۚ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","5393":"۞ إِنَّ ٱلۡإِنسَٰنَ خُلِقَ هَلُوعًا","5394":"إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعٗا","5395":"وَإِذَا مَسَّهُ ٱلۡخَيۡرُ مَنُوعًا","5396":"إِلَّا ٱلۡمُصَلِّينَ","5397":"ٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ دَآئِمُونَ","5398":"وَٱلَّذِينَ فِيٓ أَمۡوَٰلِهِمۡ حَقّٞ مَّعۡلُومٞ","5399":"لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ","5400":"وَٱلَّذِينَ يُصَدِّقُونَ بِيَوۡمِ ٱلدِّينِ","5401":"وَٱلَّذِينَ هُم مِّنۡ عَذَابِ رَبِّهِم مُّشۡفِقُونَ","5402":"إِنَّ عَذَابَ رَبِّهِمۡ غَيۡرُ مَأۡمُونٖ","5403":"وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ","5404":"إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ","5405":"فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡعَادُونَ","5406":"وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ","5407":"وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمۡ قَآئِمُونَ","5408":"وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ","5409":"أُوْلَٰٓئِكَ فِي جَنَّٰتٖ مُّكۡرَمُونَ","5595":"إِنَّ ٱلۡأَبۡرَارَ يَشۡرَبُونَ مِن كَأۡسٖ كَانَ مِزَاجُهَا كَافُورًا","5596":"عَيۡنٗا يَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفۡجِيرٗا","5597":"يُوفُونَ بِٱلنَّذۡرِ وَيَخَافُونَ يَوۡمٗا كَانَ شَرُّهُۥ مُسۡتَطِيرٗا","5598":"وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا","5599":"إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا","5600":"إِنَّا نَخَافُ مِن رَّبِّنَا يَوۡمًا عَبُوسٗا قَمۡطَرِيرٗا"},"nay":120,"nq":106};
